window.QUIZ_SETS = {"A":[{"id":"q001","source":"1. Vergara -Meccanismi delle aritmie_ automaticità, attività triggerata, rientro - 5 marzo.pdf","page":8,"topic":"Arrhythmia mechanisms","type":"mcq","prompt":"Osserva il tracciato. Perché può comparire una pausa dopo l'interruzione di una tachiaritmia atriale rapida?","options":["La via accessoria conduce solo in senso retrogrado","Il nodo AV diventa permanentemente refrattario","La ripolarizzazione ventricolare si accorcia bruscamente","La stimolazione rapida mantiene temporaneamente soppressi i pacemaker sussidiari","Il circuito di rientro continua senza attivare gli atri"],"answer":"La stimolazione rapida mantiene temporaneamente soppressi i pacemaker sussidiari","displayAnswer":"La stimolazione rapida mantiene temporaneamente soppressi i pacemaker sussidiari","explanation":"La figura mostra l'overdrive suppression: dopo pacing rapido, l'automatismo dei pacemaker secondari resta depresso finché recuperano il potenziale diastolico. Non implica un blocco AV permanente né un circuito di rientro persistente.","image":"assets/figures/00-p008.jpg","imageAlt":"Figura di riferimento da 1. Vergara -Meccanismi delle aritmie_ automaticità, attività triggerata, rientro - 5 marzo.pdf, pagina 8","imagePage":8,"set":"A"},{"id":"q008","source":"1. Vergara -Meccanismi delle aritmie_ automaticità, attività triggerata, rientro - 5 marzo.pdf","page":24,"topic":"Supraventricular tachycardia","type":"mcq","prompt":"Perché la fibrillazione atriale in un paziente con WPW può diventare particolarmente pericolosa?","options":["Il QRS stretto impedisce la degenerazione aritmica","La via accessoria può trasmettere impulsi atriali molto rapidi ai ventricoli","La via accessoria prolunga sempre il periodo refrattario","Il nodo del seno blocca tutti gli impulsi ventricolari","La fibrillazione atriale elimina la preeccitazione"],"answer":"La via accessoria può trasmettere impulsi atriali molto rapidi ai ventricoli","displayAnswer":"La via accessoria può trasmettere impulsi atriali molto rapidi ai ventricoli","explanation":"Una via accessoria con breve refrattarietà può bypassare il filtro del nodo AV e determinare frequenze ventricolari estreme, con rischio di fibrillazione ventricolare.","set":"A"},{"id":"q012","source":"10. SPECT e PET nella valutazione di sospetta CAD.pdf","page":7,"topic":"Nuclear cardiology","type":"mcq","prompt":"Una stenosi del 40-60% alla coro-TC lascia incertezza terapeutica. Quale informazione aggiuntiva è più utile prima di decidere una rivascolarizzazione?","options":["La presenza di calcio extracoronarico","La frequenza cardiaca a riposo","La rilevanza funzionale della stenosi sul flusso e sulla perfusione","Il solo diametro esterno dell'arteria","Il gruppo sanguigno del paziente"],"answer":"La rilevanza funzionale della stenosi sul flusso e sulla perfusione","displayAnswer":"La rilevanza funzionale della stenosi sul flusso e sulla perfusione","explanation":"Le stenosi intermedie richiedono una valutazione funzionale, per esempio PET/CFR, FFR-CT o perfusione, perché la percentuale anatomica da sola non definisce l'ischemia.","set":"A"},{"id":"q015","source":"10. SPECT e PET nella valutazione di sospetta CAD.pdf","page":6,"topic":"Nuclear cardiology","type":"mcq","prompt":"In quale situazione la PET con metabolismo glucidico è particolarmente utile prima di una procedura?","options":["Confermare un blocco AV completo","Valutare vitalità miocardica in un territorio disfunzionante prima di CABG o trattamento di CTO","Diagnosticare un versamento pericardico semplice","Misurare direttamente il diametro di uno stent","Sostituire la coronarografia in ogni STEMI"],"answer":"Valutare vitalità miocardica in un territorio disfunzionante prima di CABG o trattamento di CTO","displayAnswer":"Valutare vitalità miocardica in un territorio disfunzionante prima di CABG o trattamento di CTO","explanation":"La combinazione perfusione-metabolismo aiuta a distinguere miocardio vitale e ibernato da cicatrice, informazione utile quando si considera rivascolarizzazione di territori disfunzionanti.","set":"A"},{"id":"q019","source":"11. La Mura Coro-TC e RMN nella CAD.pdf","page":5,"topic":"Cardiac CT and MRI","type":"mcq","prompt":"Una placca alla coro-TC è ipodensa e mostra rimodellamento positivo. Come va interpretata?","options":["Come segno specifico di embolia polmonare","Come reperto sicuramente benigno","Come artefatto inevitabile di ogni DES","Come placca con caratteristiche di vulnerabilità, non valutabile solo dalla percentuale di stenosi","Come prova di cicatrice miocardica transmurale"],"answer":"Come placca con caratteristiche di vulnerabilità, non valutabile solo dalla percentuale di stenosi","displayAnswer":"Come placca con caratteristiche di vulnerabilità, non valutabile solo dalla percentuale di stenosi","explanation":"La composizione ipodensa e il rimodellamento positivo sono caratteristiche di placca ad alto rischio; la valutazione anatomica deve andare oltre la sola riduzione luminale.","set":"A"},{"id":"q022","source":"11. La Mura Coro-TC e RMN nella CAD.pdf","page":18,"topic":"Cardiac CT and MRI","type":"mcq","prompt":"Un paziente con quadro di STEMI ha coronarie non ostruttive. Quale esame è più utile precocemente per distinguere infarto, miocardite e Takotsubo?","options":["Risonanza magnetica cardiaca multiparametrica","Calcium score senza contrasto","Test ergometrico immediato","Ecografia carotidea","Solo radiografia del torace"],"answer":"Risonanza magnetica cardiaca multiparametrica","displayAnswer":"Risonanza magnetica cardiaca multiparametrica","explanation":"La CMR precoce combina edema, pattern di necrosi e funzione, consentendo di identificare diagnosi alternative nel sospetto MINOCA.","set":"A"},{"id":"q026","source":"12. Cirillo - Accessi vascolari arteriosi e venosi.pdf","page":12,"topic":"Vascular access safety","type":"mcq","prompt":"Quale combinazione rende una PCI tecnicamente più complessa e richiede una pianificazione più attenta dell'accesso e del supporto?","options":["Assenza di calcio e lesione breve A","Vasi piccoli o calcifici, tortuosità marcata e CTO","Ecocardiogramma completamente normale","Solo bradicardia sinusale notturna","Coronarie ampie e rettilinee senza stenosi"],"answer":"Vasi piccoli o calcifici, tortuosità marcata e CTO","displayAnswer":"Vasi piccoli o calcifici, tortuosità marcata e CTO","explanation":"Calibro ridotto, calcio, angolazioni, tortuosità e occlusioni croniche aumentano la complessità procedurale e possono richiedere dispositivi e accessi dedicati.","set":"A"},{"id":"q029","source":"13. Giugliano Accessi vascolari diagnosi e gestione delle complicanze dell'accesso.pdf","page":13,"topic":"Vascular access safety","type":"mcq","prompt":"Prima di introdurre una guaina di grosso calibro, quale controllo riduce il rischio di partire da una puntura femorale non ottimale?","options":["Iniezione ripetuta nella coronaria destra","Ablazione preventiva del nodo AV","Test all'adenosina intracoronarica","Angiografia attraverso la micropuntura o il suo dilatatore","Misurazione del QT corretto"],"answer":"Angiografia attraverso la micropuntura o il suo dilatatore","displayAnswer":"Angiografia attraverso la micropuntura o il suo dilatatore","explanation":"La micropuntura consente di verificare la posizione prima di dilatare il tramite, particolarmente importante quando l'accesso dovrà ospitare dispositivi di grande calibro.","set":"A"},{"id":"q033","source":"14. Bardi Coronarografia- identificazione della CAD ostruttiva.pdf","page":11,"topic":"Coronary angiography","type":"mcq","prompt":"Alla scala TIMI del trombo, quale passaggio descrive il massimo grado?","options":["Solo irregolarità parietale senza trombo","Stenosi calcifica senza materiale trombotico","Assenza completa di trombo","Trombo occludente con assenza di flusso anterogrado","Flusso normale con blush miocardico conservato"],"answer":"Trombo occludente con assenza di flusso anterogrado","displayAnswer":"Trombo occludente con assenza di flusso anterogrado","explanation":"La scala va dal grado 0, nessun trombo, al grado 5, occlusione trombotica completa. Non va confusa con la classificazione del flusso TIMI.","set":"A"},{"id":"q037","source":"14. Bardi Coronarografia- identificazione della CAD ostruttiva.pdf","page":20,"topic":"Coronary angiography","type":"mcq","prompt":"Dopo impianto di più stent, l'angiografia suggerisce sottoespansione. Quale metodica è più adatta a confermare il problema e guidare l'ottimizzazione?","options":["Sola radiografia del torace","Ecografia carotidea","Holter ECG","Test da sforzo immediato","IVUS"],"answer":"IVUS","displayAnswer":"IVUS","explanation":"L'IVUS visualizza area luminale, apposizione ed espansione dello stent e può guidare una post-dilatazione mirata; la sola angiografia può sottostimare la sottoespansione.","set":"A"},{"id":"q041","source":"16. Piccolo Rivascolarizzazione nel paziente con disfunzione ventricolare sinistra.pdf","page":10,"topic":"Revascularization and LV dysfunction","type":"mcq","prompt":"Nel trial REVIVED, l'aggiunta di PCI alla terapia medica ottimale nei pazienti con grave disfunzione ischemica non ha ridotto l'endpoint principale. Quale interpretazione è corretta?","options":["La terapia medica deve essere sospesa dopo PCI","La PCI è controindicata in qualunque paziente con angina","La vitalità non esiste nei pazienti con CAD","Il CABG e la PCI sono equivalenti in ogni anatomia","La PCI non va proposta automaticamente per migliorare la prognosi in ogni cardiomiopatia ischemica stabile"],"answer":"La PCI non va proposta automaticamente per migliorare la prognosi in ogni cardiomiopatia ischemica stabile","displayAnswer":"La PCI non va proposta automaticamente per migliorare la prognosi in ogni cardiomiopatia ischemica stabile","explanation":"Il risultato invita a distinguere sollievo sintomatico, anatomia e obiettivo prognostico. Non esclude PCI per sintomi o indicazioni specifiche, ma nega una strategia automatica universale.","set":"A"},{"id":"q045","source":"17. Ass. Pilato Rivascolarizzazione miocardica chirurgica.pdf","page":5,"topic":"Surgical revascularization","type":"mcq","prompt":"Osserva i diversi accessi chirurgici. Qual è il vantaggio principale di un approccio mininvasivo o ibrido in un paziente selezionato?","options":["Ridurre il trauma chirurgico mantenendo una rivascolarizzazione mirata di qualità","Evitare ogni uso di graft arteriosi","Sostituire la terapia antitrombotica in ogni caso","Eliminare il rischio di conversione","Garantire sempre una rivascolarizzazione completa senza selezione"],"answer":"Ridurre il trauma chirurgico mantenendo una rivascolarizzazione mirata di qualità","displayAnswer":"Ridurre il trauma chirurgico mantenendo una rivascolarizzazione mirata di qualità","explanation":"Approcci mininvasivi e ibridi possono combinare un graft chirurgico di valore, spesso LIMA-IVA, con PCI su altri vasi. La selezione anatomica e l'esperienza restano decisive.","image":"assets/figures/07-p005.jpg","imageAlt":"Figura di riferimento da 17. Ass. Pilato Rivascolarizzazione miocardica chirurgica.pdf, pagina 5","imagePage":5,"set":"A"},{"id":"q050","source":"17. Ass. Pilato Rivascolarizzazione miocardica chirurgica.pdf","page":10,"topic":"Surgical revascularization","type":"mcq","prompt":"Che cosa definisce una rivascolarizzazione ibrida?","options":["Due PCI eseguite in giorni diversi","Impianto di pacemaker durante coronarografia","Combinazione pianificata di graft chirurgico e PCI su territori differenti","CABG seguito sempre da trapianto","Uso simultaneo di due antiaggreganti"],"answer":"Combinazione pianificata di graft chirurgico e PCI su territori differenti","displayAnswer":"Combinazione pianificata di graft chirurgico e PCI su territori differenti","explanation":"La strategia ibrida sfrutta punti di forza complementari, per esempio LIMA-IVA chirurgica e PCI sugli altri vasi, con tempi e sequenza concordati dall'Heart Team.","set":"A"},{"id":"q054","source":"18. Piccolo Rivascolarizzazione miocardica nelle sindromi coronariche acute.pdf","page":12,"topic":"ACS revascularization","type":"mcq","prompt":"Un paziente con STEMI si presenta 18 ore dopo l'esordio ed è ancora sintomatico con ischemia persistente. Qual è l'approccio più appropriato?","options":["Dimissione immediata","Solo test ergometrico","Attendere la normalizzazione spontanea della troponina","Nessuna coronarografia perché sono trascorse 12 ore","Strategia invasiva urgente con riperfusione se indicata"],"answer":"Strategia invasiva urgente con riperfusione se indicata","displayAnswer":"Strategia invasiva urgente con riperfusione se indicata","explanation":"Il tempo trascorso non annulla l'indicazione quando persistono ischemia, instabilità o sintomi. La presentazione tardiva va interpretata nel contesto clinico.","set":"A"},{"id":"q057","source":"18. Piccolo Rivascolarizzazione miocardica nelle sindromi coronariche acute.pdf","page":26,"topic":"ACS revascularization","type":"mcq","prompt":"Quale popolazione richiede cautela nell'estendere automaticamente i risultati dei trial di PCI completa?","options":["Pazienti con shock cardiogeno o CTO, spesso esclusi o poco rappresentati","Pazienti stabili con singola lesione semplice","Pazienti senza CAD","Pazienti con sola ipertensione controllata","Soggetti con ECG normale e nessun sintomo"],"answer":"Pazienti con shock cardiogeno o CTO, spesso esclusi o poco rappresentati","displayAnswer":"Pazienti con shock cardiogeno o CTO, spesso esclusi o poco rappresentati","explanation":"Shock e CTO hanno complessità e rischi diversi e sono stati frequentemente esclusi dai trial sulle non culprit; l'evidenza non va trasferita senza giudizio.","set":"A"},{"id":"q061","source":"19. Piccolo Shock cardiogeno - rivascolarizzazione e supporto al circolo.pdf","page":13,"topic":"Cardiogenic shock","type":"mcq","prompt":"Perché aumentare molto il flusso dell'ECMO VA può peggiorare la distensione del ventricolo sinistro?","options":["Elimina il consumo di ossigeno miocardico","Riduce sempre la pressione aortica","Apre automaticamente la valvola aortica","Diminuisce il ritorno venoso a zero","Aumenta il postcarico aortico contro cui il ventricolo deve eiettare"],"answer":"Aumenta il postcarico aortico contro cui il ventricolo deve eiettare","displayAnswer":"Aumenta il postcarico aortico contro cui il ventricolo deve eiettare","explanation":"Il flusso retrogrado arterioso dell'ECMO può aumentare postcarico, pressione atriale sinistra e congestione. Il supporto non equivale automaticamente a unloading.","set":"A"},{"id":"q065","source":"19. Piccolo Shock cardiogeno - rivascolarizzazione e supporto al circolo.pdf","page":21,"topic":"Cardiogenic shock","type":"mcq","prompt":"In uno shock da infarto multivasale, quale strategia coronarica è generalmente favorita nella fase iniziale?","options":["CABG in tutti senza angiografia","PCI della sola lesione culprit, con eventuale trattamento differito delle altre lesioni","Solo fibrinolisi dopo PCI","PCI immediata obbligatoria di ogni stenosi","Nessuna riperfusione"],"answer":"PCI della sola lesione culprit, con eventuale trattamento differito delle altre lesioni","displayAnswer":"PCI della sola lesione culprit, con eventuale trattamento differito delle altre lesioni","explanation":"Nel paziente in shock la PCI multivasale immediata può aumentare contrasto, durata e complicanze. La priorità è riperfondere rapidamente la culprit e stabilizzare.","set":"A"},{"id":"q069","source":"2. Strisciuglio - Lo studio elettrofisiologico_ indicazioni, tecnica di esecuzione, parametri registrati - 5 marzo.pdf","page":25,"topic":"Electrophysiology","type":"mcq","prompt":"Perché il contatto efficace catetere-miocardio è essenziale durante RF?","options":["Elimina il rischio di perforazione","Blocca meccanicamente la coronaria","Permette trasferimento controllato di energia e formazione di una lesione adeguata","Rende inutile irrigazione e temperatura","Aumenta sempre la profondità indipendentemente dalla potenza"],"answer":"Permette trasferimento controllato di energia e formazione di una lesione adeguata","displayAnswer":"Permette trasferimento controllato di energia e formazione di una lesione adeguata","explanation":"Contatto insufficiente produce lesioni inefficaci; pressione eccessiva aumenta rischi. La qualità dipende dall'equilibrio tra contatto, potenza, tempo e raffreddamento.","set":"A"},{"id":"q073","source":"20. Di Serafino Fisiologia coronarica nel paziente candidato a rivascolarizzazione coronarica; ANOCA e INOCA.pdf","page":12,"topic":"Coronary physiology and INOCA","type":"mcq","prompt":"Osserva i criteri COVADIS. Un paziente ha angina, coronarie non ostruttive e ischemia documentata, ma non è stato ancora definito il meccanismo. Quale categoria descrive meglio il quadro?","options":["Blocco AV completo","Sindrome di Brugada","STEMI con occlusione","INOCA, da fenotipizzare con test della funzione coronarica","MINOCA certo"],"answer":"INOCA, da fenotipizzare con test della funzione coronarica","displayAnswer":"INOCA, da fenotipizzare con test della funzione coronarica","explanation":"INOCA indica ischemia con arterie non ostruttive. La diagnosi è un punto di partenza: CFR, IMR e test all'acetilcolina distinguono disfunzione microvascolare e vasospasmo.","image":"assets/figures/11-p012.jpg","imageAlt":"Figura di riferimento da 20. Di Serafino Fisiologia coronarica nel paziente candidato a rivascolarizzazione coronarica; ANOCA e INOCA.pdf, pagina 12","imagePage":12,"set":"A"},{"id":"q078","source":"20. Di Serafino Fisiologia coronarica nel paziente candidato a rivascolarizzazione coronarica; ANOCA e INOCA.pdf","page":11,"topic":"Coronary physiology and INOCA","type":"mcq","prompt":"Un paziente ha CFR ridotta e IMR elevato in assenza di stenosi epicardica significativa. Quale endotipo è più probabile?","options":["Pericardite isolata","Occlusione acuta del tronco comune","WPW","Conduzione AV nodale duale","Disfunzione microvascolare strutturale"],"answer":"Disfunzione microvascolare strutturale","displayAnswer":"Disfunzione microvascolare strutturale","explanation":"CFR bassa indica capacità vasodilatatoria ridotta; IMR elevato localizza una resistenza microvascolare anomala. La combinazione supporta CMD strutturale.","set":"A"},{"id":"q082","source":"23. Di Seraf.  MINOCA (by giovanni vitale.pdf","page":1,"topic":"MINOCA","type":"mcq","prompt":"Quale combinazione definisce correttamente un working diagnosis di MINOCA?","options":["Angina senza aumento di troponina","Miocardite già dimostrata alla CMR","Criteri di infarto miocardico, nessuna stenosi coronarica ostruttiva e nessuna causa alternativa evidente iniziale","Stenosi del 100% della culprit","Solo dolore toracico con ECG normale"],"answer":"Criteri di infarto miocardico, nessuna stenosi coronarica ostruttiva e nessuna causa alternativa evidente iniziale","displayAnswer":"Criteri di infarto miocardico, nessuna stenosi coronarica ostruttiva e nessuna causa alternativa evidente iniziale","explanation":"MINOCA richiede un vero infarto e coronarie non ostruttive, dopo esclusione iniziale di spiegazioni alternative. È una diagnosi di lavoro da approfondire.","set":"A"},{"id":"q085","source":"23. Di Seraf.  MINOCA (by giovanni vitale.pdf","page":3,"topic":"MINOCA","type":"mcq","prompt":"CFR e IMR vengono misurati durante iperemia massimale. Qual è lo scopo dell'adenosina?","options":["Ridurre al minimo e stabilizzare la resistenza microvascolare per valutare la capacità di flusso","Misurare il calcio coronarico","Indurre trombosi coronarica","Aumentare selettivamente la stenosi anatomica","Bloccare permanentemente il nodo AV"],"answer":"Ridurre al minimo e stabilizzare la resistenza microvascolare per valutare la capacità di flusso","displayAnswer":"Ridurre al minimo e stabilizzare la resistenza microvascolare per valutare la capacità di flusso","explanation":"L'iperemia rende interpretabili rapporti pressori e di flusso. L'adenosina non identifica da sola lo spasmo epicardico, che richiede test vasomotori dedicati.","set":"A"},{"id":"q089","source":"23. MINOCA, MANCA SIA LEZ CHE SBOB.pdf","page":7,"topic":"Procedural safety","type":"mcq","prompt":"Durante angiografia della coronaria destra, quale comportamento riduce il rischio di ischemia iatrogena e aritmie?","options":["Ignorare lo smorzamento pressorio","Aumentare sempre volume e velocità","Ripetere iniezioni senza pausa","Occludere l'ostio con il catetere","Attendere il washout del contrasto e monitorare pressione ed ECG tra le iniezioni"],"answer":"Attendere il washout del contrasto e monitorare pressione ed ECG tra le iniezioni","displayAnswer":"Attendere il washout del contrasto e monitorare pressione ed ECG tra le iniezioni","explanation":"Iniezioni ravvicinate o con catetere incuneato possono ridurre il flusso e provocare ischemia o fibrillazione ventricolare. La sicurezza dipende anche dal ritmo della procedura.","set":"A"},{"id":"q093","source":"25-26 Franzone - Terapia medica ottimale nelle sindromi coronariche acute e croniche.pdf","page":5,"topic":"Antiplatelet and medical therapy","type":"mcq","prompt":"Dopo una SCA trattata con PCI, qual è la strategia antiaggregante di default se il rischio emorragico non è elevato?","options":["Aspirina a bassa dose più un inibitore P2Y12","Aspirina ad alte dosi da sola","Nessun antiaggregante dopo lo stent","Anticoagulante orale triplo indefinito","Solo dipiridamolo"],"answer":"Aspirina a bassa dose più un inibitore P2Y12","displayAnswer":"Aspirina a bassa dose più un inibitore P2Y12","explanation":"La DAPT riduce trombosi di stent ed eventi ischemici. Durata e scelta del P2Y12 vengono adattate a rischio ischemico, emorragico e indicazione a anticoagulazione.","set":"A"},{"id":"q097","source":"25-26 Franzone - Terapia medica ottimale nelle sindromi coronariche acute e croniche.pdf","page":16,"topic":"Antiplatelet and medical therapy","type":"mcq","prompt":"Nel passaggio tra prasugrel e ticagrelor, quale precauzione evita sovrapposizione o gap farmacodinamico?","options":["Interrompere anche l'aspirina per mesi","Seguire timing e dose di carico previsti, considerando l'ultima dose assunta","Cambiare senza conoscere l'orario precedente","Aggiungere warfarin in tutti","Misurare soltanto la pressione"],"answer":"Seguire timing e dose di carico previsti, considerando l'ultima dose assunta","displayAnswer":"Seguire timing e dose di carico previsti, considerando l'ultima dose assunta","explanation":"Entrambi sono potenti P2Y12, ma hanno farmacologia diversa. Il cambio va pianificato, non improvvisato, soprattutto nella fase ad alto rischio.","set":"A"},{"id":"q101","source":"28. Cirillo Terapia antitrombotica nelle sindromi coronariche acute - dal pretrattamento alla dimissione.pdf","page":9,"topic":"Antithrombotic therapy","type":"mcq","prompt":"Qual è il principale limite di un pretrattamento P2Y12 indiscriminato prima di conoscere l'anatomia coronarica?","options":["Può aumentare sanguinamento o complicare un CABG urgente senza beneficio certo","Elimina l'effetto dell'eparina","Riduce la troponina a zero","Causa necessariamente trombosi di stent","Impedisce sempre l'accesso radiale"],"answer":"Può aumentare sanguinamento o complicare un CABG urgente senza beneficio certo","displayAnswer":"Può aumentare sanguinamento o complicare un CABG urgente senza beneficio certo","explanation":"Il valore del pretrattamento dipende da diagnosi, tempo alla coronarografia e probabilità di chirurgia; la potenza antiplatelet ha un costo emorragico.","set":"A"},{"id":"q105","source":"28. Cirillo Terapia antitrombotica nelle sindromi coronariche acute - dal pretrattamento alla dimissione.pdf","page":19,"topic":"Antithrombotic therapy","type":"mcq","prompt":"Quale paziente può trarre maggior valore da una de-escalation P2Y12 guidata da genotipo o funzione piastrinica?","options":["Chi presenta solo ipertensione","Chi deve iniziare beta-bloccante","Chi non assume alcun antiaggregante","Chi necessita di ridurre intensità ma presenta rischio di scarsa risposta al clopidogrel","Chi ha una CTO senza PCI"],"answer":"Chi necessita di ridurre intensità ma presenta rischio di scarsa risposta al clopidogrel","displayAnswer":"Chi necessita di ridurre intensità ma presenta rischio di scarsa risposta al clopidogrel","explanation":"I test possono identificare pazienti nei quali clopidogrel sarebbe insufficiente, evitando una de-escalation cieca; non sono necessari in ogni caso.","set":"A"},{"id":"q107","source":"3. Rapacciuolo - Disfunzione del nodo del seno e del nodo AV- fisiopatologia, test diagnostici, trattamento.pdf","page":16,"topic":"Bradyarrhythmias","type":"mcq","prompt":"Osserva l'algoritmo. Qual è il principio centrale prima di impiantare un pacemaker per bradicardia?","options":["Documentare la correlazione tra sintomi e disturbo del ritmo quando possibile","Ignorare cause reversibili","Impiantare per ogni frequenza <60/min","Richiedere sempre una coronarografia","Basarsi solo sull'età"],"answer":"Documentare la correlazione tra sintomi e disturbo del ritmo quando possibile","displayAnswer":"Documentare la correlazione tra sintomi e disturbo del ritmo quando possibile","explanation":"La decisione dipende da tipo di blocco, sintomi, prognosi e reversibilità. Una frequenza bassa isolata non basta in tutti i contesti.","image":"assets/figures/16-p016.jpg","imageAlt":"Figura di riferimento da 3. Rapacciuolo - Disfunzione del nodo del seno e del nodo AV- fisiopatologia, test diagnostici, trattamento.pdf, pagina 16","imagePage":16,"set":"A"},{"id":"q114","source":"3. Rapacciuolo - Disfunzione del nodo del seno e del nodo AV- fisiopatologia, test diagnostici, trattamento.pdf","page":13,"topic":"Bradyarrhythmias","type":"mcq","prompt":"Cadute ricorrenti inspiegate in un anziano possono rappresentare quale problema occulto?","options":["Sempre una crisi epilettica","Unicamente debolezza muscolare","Solo ipoglicemia","Sincope bradiaritmica non riconosciuta","Necessariamente vasospasmo"],"answer":"Sincope bradiaritmica non riconosciuta","displayAnswer":"Sincope bradiaritmica non riconosciuta","explanation":"Le cadute senza spiegazione meritano un percorso simile alla sincope, includendo anamnesi, ECG e monitoraggio prolungato quando appropriato.","set":"A"},{"id":"q118","source":"31. Spaccarotella Dissezioni Coronariche Spontanee (1).pdf","page":16,"topic":"SCAD","type":"mcq","prompt":"Quando IVUS o OCT può essere utile nella SCAD?","options":["Per misurare la riserva coronarica","Quando la diagnosi o la posizione della guida nel vero lume è incerta e l'informazione cambia la gestione","Per trattare la bradicardia","In ogni caso stabile per obbligo","Per sostituire il monitoraggio clinico"],"answer":"Quando la diagnosi o la posizione della guida nel vero lume è incerta e l'informazione cambia la gestione","displayAnswer":"Quando la diagnosi o la posizione della guida nel vero lume è incerta e l'informazione cambia la gestione","explanation":"L'imaging intracoronarico può mostrare doppio lume o ematoma, ma l'introduzione della guida e il contrasto hanno rischi: va usato selettivamente.","set":"A"},{"id":"q121","source":"31. Spaccarotella Dissezioni Coronariche Spontanee (1).pdf","page":14,"topic":"SCAD","type":"mcq","prompt":"Una lunga riduzione di calibro senza aterosclerosi in una donna con NSTEMI suggerisce SCAD. Quale errore va evitato?","options":["Interpretarla automaticamente come vasospasmo o malattia aterosclerotica diffusa","Rivedere le immagini in più proiezioni","Monitorare dolore ed ECG","Considerare imaging selettivo","Valutare il contesto clinico"],"answer":"Interpretarla automaticamente come vasospasmo o malattia aterosclerotica diffusa","displayAnswer":"Interpretarla automaticamente come vasospasmo o malattia aterosclerotica diffusa","explanation":"I pattern angiografici di SCAD possono mimare spasmo e aterosclerosi. Una diagnosi errata può portare a PCI o terapia non necessarie.","set":"A"},{"id":"q125","source":"32. Losi - complicanze meccaniche dell' infarto.pdf","page":7,"topic":"Mechanical complications of MI","type":"mcq","prompt":"Dopo infarto inferiore, un paziente sviluppa edema polmonare e rigurgito mitralico acuto senza grande dilatazione del ventricolo. Qual è il meccanismo più probabile?","options":["Aumento della CFR","Difetto interatriale","Blocco seno-atriale","Stenosi mitralica cronica","Rottura o disfunzione ischemica del muscolo papillare"],"answer":"Rottura o disfunzione ischemica del muscolo papillare","displayAnswer":"Rottura o disfunzione ischemica del muscolo papillare","explanation":"L'insufficienza mitralica acuta può causare edema severo con atrio non adattato. Il muscolo papillare posteromediale è vulnerabile per la sua singola vascolarizzazione.","set":"A"},{"id":"q129","source":"32. Losi - complicanze meccaniche dell' infarto.pdf","page":3,"topic":"Mechanical complications of MI","type":"mcq","prompt":"Nel sospetto infarto del ventricolo destro, quale intervento può peggiorare rapidamente la pressione se usato senza cautela?","options":["Riperfusione della coronaria destra","Correzione di bradicardia significativa","Monitoraggio ECG","Riduzione eccessiva del precarico con nitrati o diuretici","Valutazione ecografica"],"answer":"Riduzione eccessiva del precarico con nitrati o diuretici","displayAnswer":"Riduzione eccessiva del precarico con nitrati o diuretici","explanation":"Il ventricolo destro ischemico è precarico-dipendente. Vasodilatazione o diuresi eccessive possono ridurre il riempimento e la portata.","set":"A"},{"id":"q133","source":"4. Pergola - Short QT, Long QT, TV idiopatica.pdf","page":16,"topic":"Inherited repolarization disorders","type":"mcq","prompt":"Un paziente con sospetta LQTS ha QTc 445 ms a riposo. Quale affermazione è corretta?","options":["Esclude definitivamente la diagnosi","Un QTc borderline non esclude LQTS e va integrato con storia, dinamica e score","Conferma automaticamente LQTS","Richiede ICD immediato in ogni caso","Dimostra QT corto"],"answer":"Un QTc borderline non esclude LQTS e va integrato con storia, dinamica e score","displayAnswer":"Un QTc borderline non esclude LQTS e va integrato con storia, dinamica e score","explanation":"La penetranza è variabile e il QT può essere borderline. ECG seriati, Holter, test dinamici, anamnesi e genetica possono aumentare o ridurre la probabilità.","set":"A"},{"id":"q137","source":"4. Pergola - Short QT, Long QT, TV idiopatica.pdf","page":41,"topic":"Idiopathic ventricular tachycardia","type":"mcq","prompt":"Una TV monomorfa sostenuta in un cuore apparentemente normale richiede quale approccio iniziale?","options":["Ignorare la CMR","Considerarla sempre benigna","Trattarla come fibrillazione atriale","Definire morfologia e sede d'origine, escludendo cardiopatia strutturale o genetica","Diagnosticare automaticamente infarto"],"answer":"Definire morfologia e sede d'origine, escludendo cardiopatia strutturale o genetica","displayAnswer":"Definire morfologia e sede d'origine, escludendo cardiopatia strutturale o genetica","explanation":"Le TV idiopatiche hanno pattern e meccanismi specifici, ma la diagnosi richiede esclusione di cicatrice, cardiomiopatia e sindromi ereditarie.","set":"A"},{"id":"q141","source":"5. Rapacciuolo prevenzione SCD + dispositivi per HF 2.pdf","page":5,"topic":"Sudden cardiac death and devices","type":"mcq","prompt":"Quale reperto caratterizza la cardiomiopatia aritmogena e contribuisce al rischio ventricolare?","options":["Aumento uniforme di IKs","Ipertrofia isolata del nodo AV","Calcificazione esclusiva della valvola mitrale","Sostituzione fibro-adiposa del miocardio, spesso del ventricolo destro","Via accessoria atrioventricolare"],"answer":"Sostituzione fibro-adiposa del miocardio, spesso del ventricolo destro","displayAnswer":"Sostituzione fibro-adiposa del miocardio, spesso del ventricolo destro","explanation":"Il tessuto fibro-adiposo crea un substrato di conduzione lenta e rientro. Il coinvolgimento può estendersi anche al ventricolo sinistro.","set":"A"},{"id":"q145","source":"5. Rapacciuolo prevenzione SCD + dispositivi per HF 2.pdf","page":29,"topic":"Sudden cardiac death and devices","type":"mcq","prompt":"Un sistema CCM migliora sintomi ma non eroga terapia antitachicardica. Cosa va valutato prima dell'impianto?","options":["Se la coro-TC è normale","Se l'aspirina è tollerata","Se il paziente ha anche indicazione a ICD o CRT-D per prevenzione della morte improvvisa","Se può sospendere tutti i farmaci","Se presenta una via accessoria"],"answer":"Se il paziente ha anche indicazione a ICD o CRT-D per prevenzione della morte improvvisa","displayAnswer":"Se il paziente ha anche indicazione a ICD o CRT-D per prevenzione della morte improvvisa","explanation":"I dispositivi hanno funzioni differenti. CCM non sostituisce defibrillazione o resincronizzazione quando queste sono indicate.","set":"A"},{"id":"q146","source":"5. Vergara -CRT e ICD Trial Clinici-.pdf","page":10,"topic":"Cardiac resynchronization therapy","type":"mcq","prompt":"Osserva il confronto tra i trial sulla cardiomiopatia non ischemica. Perché DANISH ha mostrato un beneficio dell'ICD meno evidente rispetto a studi precedenti?","options":["La cardiomiopatia non ischemica non causa aritmie","Tutti i pazienti avevano una via accessoria","La terapia moderna dello scompenso e la CRT hanno ridotto la quota di morte improvvisa prevenibile dall'ICD","DANISH includeva soltanto pazienti con STEMI acuto","L'ICD non interrompe mai la fibrillazione ventricolare"],"answer":"La terapia moderna dello scompenso e la CRT hanno ridotto la quota di morte improvvisa prevenibile dall'ICD","displayAnswer":"La terapia moderna dello scompenso e la CRT hanno ridotto la quota di morte improvvisa prevenibile dall'ICD","explanation":"Il beneficio assoluto di un ICD dipende dal rischio residuo di morte aritmica e dalla competizione con altre cause di morte. Terapia contemporanea, CRT ed età possono attenuarlo.","image":"assets/figures/21-p010.jpg","imageAlt":"Figura di riferimento da 5. Vergara -CRT e ICD Trial Clinici-.pdf, pagina 10","imagePage":10,"set":"A"},{"id":"q153","source":"6 Strisciugno Sincope.pdf","page":5,"topic":"Syncope","type":"mcq","prompt":"Durante massaggio del seno carotideo compaiono asistolia e sintomi, corretti dall'atropina. Quale componente domina?","options":["Embolia coronarica","Tachicardia ventricolare","Risposta cardioinibitoria","Disfunzione microvascolare","Risposta vasodepressiva pura"],"answer":"Risposta cardioinibitoria","displayAnswer":"Risposta cardioinibitoria","explanation":"L'asistolia reversibile con aumento della frequenza indica componente cardioinibitoria; una caduta pressoria persistente nonostante ritmo corretto suggerisce vasodepressione.","set":"A"},{"id":"q157","source":"6 Strisciugno Sincope.pdf","page":10,"topic":"Syncope","type":"mcq","prompt":"In uno studio di pacing closed-loop per sincope riflessa selezionata, qual è il razionale del sensore CLS?","options":["Defibrillare la FV","Rilevare precocemente variazioni correlate alla contrattilità e aumentare il pacing prima della bradicardia marcata","Bloccare la COX-1","Ridurre il calcio coronarico","Misurare FFR"],"answer":"Rilevare precocemente variazioni correlate alla contrattilità e aumentare il pacing prima della bradicardia marcata","displayAnswer":"Rilevare precocemente variazioni correlate alla contrattilità e aumentare il pacing prima della bradicardia marcata","explanation":"L'algoritmo tenta di intervenire nella fase precoce del riflesso. Il beneficio dipende dalla selezione di pazienti con componente cardioinibitoria rilevante.","set":"A"},{"id":"q161","source":"6. Strisciuglio Wolff Parkinson White.pdf","page":4,"topic":"WPW and accessory pathways","type":"mcq","prompt":"La preeccitazione scompare bruscamente durante sforzo. Come va interpretato il reperto?","options":["Conferma AVNRT","Dimostra rischio massimo","Suggerisce una via con refrattarietà più lunga, ma non garantisce da solo benignità assoluta","Impone ICD","Esclude qualunque via accessoria"],"answer":"Suggerisce una via con refrattarietà più lunga, ma non garantisce da solo benignità assoluta","displayAnswer":"Suggerisce una via con refrattarietà più lunga, ma non garantisce da solo benignità assoluta","explanation":"La perdita improvvisa è rassicurante, ma sensibilità e riproducibilità sono limitate. La stratificazione integra clinica e, quando indicato, SEF.","set":"A"},{"id":"q165","source":"6. Strisciuglio Wolff Parkinson White.pdf","page":14,"topic":"WPW and accessory pathways","type":"mcq","prompt":"Qual è l'endpoint immediato dell'ablazione di una via accessoria manifesta?","options":["Riduzione della FE","Perdita della conduzione attraverso la via in entrambe le direzioni rilevanti","Persistenza della tachicardia clinica","Induzione obbligatoria di fibrillazione atriale","Aumento dell'onda delta"],"answer":"Perdita della conduzione attraverso la via in entrambe le direzioni rilevanti","displayAnswer":"Perdita della conduzione attraverso la via in entrambe le direzioni rilevanti","explanation":"Si verifica scomparsa della preeccitazione e assenza di conduzione retrograda accessoria, con periodo di osservazione e manovre di conferma.","set":"A"},{"id":"q169","source":"7. Vergara Tachicardia da rientro nodale 2.pdf","page":14,"topic":"AVNRT","type":"mcq","prompt":"Nel fenomeno double fire, come può una singola attivazione atriale generare due risposte ventricolari?","options":["Una via accessoria duplica il QRS senza nodo AV","Due nodi del seno scaricano insieme","L'impulso percorre sia via rapida sia via lenta con separazione sufficiente per attivare due volte il sistema His-Purkinje","La fibrillazione atriale diventa regolare","Un pacemaker eroga due shock"],"answer":"L'impulso percorre sia via rapida sia via lenta con separazione sufficiente per attivare due volte il sistema His-Purkinje","displayAnswer":"L'impulso percorre sia via rapida sia via lenta con separazione sufficiente per attivare due volte il sistema His-Purkinje","explanation":"La doppia risposta nodale richiede conduzione duale e timing che eviti la collisione; può mimare extrasistolia o tachicardia.","set":"A"},{"id":"q173","source":"8. Vergara Sindromi Genetiche Vergara (Brugada, ER, CPVT) 2.pdf","page":7,"topic":"Inherited arrhythmia syndromes","type":"mcq","prompt":"Osserva lo Shanghai score. Qual è il suo uso più corretto nel sospetto Brugada?","options":["Decidere automaticamente ICD per ogni punteggio","Integrare ECG, storia clinica, familiarità e genetica per stimare la probabilità diagnostica","Sostituire il giudizio clinico con un singolo ECG","Misurare il rischio emorragico","Diagnosticare WPW"],"answer":"Integrare ECG, storia clinica, familiarità e genetica per stimare la probabilità diagnostica","displayAnswer":"Integrare ECG, storia clinica, familiarità e genetica per stimare la probabilità diagnostica","explanation":"Lo score organizza evidenze eterogenee. Un pattern tipo 1 spontaneo ha peso diverso da un reperto solo farmacologico e il punteggio non coincide con la sola prognosi.","image":"assets/figures/25-p007.jpg","imageAlt":"Figura di riferimento da 8. Vergara Sindromi Genetiche Vergara (Brugada, ER, CPVT) 2.pdf, pagina 7","imagePage":7,"set":"A"},{"id":"q177","source":"8. Vergara Sindromi Genetiche Vergara (Brugada, ER, CPVT) 2.pdf","page":19,"topic":"Inherited arrhythmia syndromes","type":"mcq","prompt":"Un Brugada risk score pari a zero è più utile per quale informazione?","options":["Identificare un gruppo con probabilità relativamente bassa di eventi","Escludere il follow-up per sempre","Predire con certezza chi avrà FV","Indicare ICD in tutti","Diagnosticare CPVT"],"answer":"Identificare un gruppo con probabilità relativamente bassa di eventi","displayAnswer":"Identificare un gruppo con probabilità relativamente bassa di eventi","explanation":"Molti score hanno valore predittivo negativo migliore di quello positivo; aiutano la conversazione sul rischio ma non danno certezze individuali.","set":"A"},{"id":"q181","source":"9. Ciampi Ecostress.pdf","page":7,"topic":"Stress echocardiography","type":"mcq","prompt":"Osserva la scala delle linee B. Quale cambiamento durante stress indica congestione polmonare inducibile?","options":["Aumento del numero e della confluenza delle linee B","Aumento del calcio coronarico","Scomparsa di ogni artefatto verticale","Comparsa di onda delta","Riduzione della frequenza cardiaca"],"answer":"Aumento del numero e della confluenza delle linee B","displayAnswer":"Aumento del numero e della confluenza delle linee B","explanation":"Le linee B riflettono acqua extravascolare polmonare. La loro dinamica aggiunge informazione oltre la sola cinetica regionale.","image":"assets/figures/26-p007.jpg","imageAlt":"Figura di riferimento da 9. Ciampi Ecostress.pdf, pagina 7","imagePage":7,"set":"A"},{"id":"q188","source":"9. Ciampi Ecostress.pdf","page":20,"topic":"Stress echocardiography","type":"mcq","prompt":"Qual è il vantaggio del protocollo ABCDE rispetto alla sola valutazione della cinetica?","options":["Elimina la necessità di monitoraggio","Serve esclusivamente nelle valvulopatie","Misura solo la stenosi anatomica","Integra ischemia, congestione, riserva contrattile, flusso coronarico e risposta autonomica","Riduce l'esame a un singolo fotogramma"],"answer":"Integra ischemia, congestione, riserva contrattile, flusso coronarico e risposta autonomica","displayAnswer":"Integra ischemia, congestione, riserva contrattile, flusso coronarico e risposta autonomica","explanation":"La valutazione multiparametrica descrive più dimensioni della vulnerabilità e può essere utile anche in INOCA, scompenso e altre condizioni.","set":"A"},{"id":"q192","source":"Lezione Gargiulo 2026.pdf","page":8,"topic":"ACS risk and antithrombotic strategy","type":"mcq","prompt":"Qual è il razionale delle strategie DAPT abbreviate nei pazienti selezionati?","options":["La maggior parte del beneficio antitrombotico precoce può essere mantenuta riducendo l'esposizione emorragica tardiva","Il sanguinamento non influenza la prognosi","L'aspirina aumenta sempre l'ischemia","Ogni paziente deve sospendere tutto dopo 24 ore","Lo stent non trombizza mai"],"answer":"La maggior parte del beneficio antitrombotico precoce può essere mantenuta riducendo l'esposizione emorragica tardiva","displayAnswer":"La maggior parte del beneficio antitrombotico precoce può essere mantenuta riducendo l'esposizione emorragica tardiva","explanation":"Stent moderni e selezione del rischio permettono semplificazione in alcuni pazienti. Il timing non è uguale per tutte le SCA.","set":"A"},{"id":"q195","source":"Lezione Gargiulo 2026.pdf","page":16,"topic":"ACS diagnosis","type":"mcq","prompt":"Sopraslivellamento in DI, aVL e V2 con sottoslivellamento in DIII può suggerire quale evento?","options":["Pericardite diffusa certa","Occlusione di un ramo diagonale o intermedio con ischemia laterale alta","Infarto del ventricolo destro isolato","Blocco AV completo","WPW"],"answer":"Occlusione di un ramo diagonale o intermedio con ischemia laterale alta","displayAnswer":"Occlusione di un ramo diagonale o intermedio con ischemia laterale alta","explanation":"Il South African flag sign collega derivazioni non contigue sul layout ma contigue anatomicamente. Può rappresentare un OMI senza criteri STEMI convenzionali.","set":"A"},{"id":"q199","source":"guidelines 2023-SCA.pdf","page":55,"topic":"ACS guidelines","type":"mcq","prompt":"Dopo angiografia non ostruttiva in un paziente con infarto, quale sequenza rispecchia l'algoritmo MINOCA?","options":["Eseguire solo test ergometrico","Impiantare ICD senza ulteriori dati","Prescrivere DAPT a vita a tutti","Escludere diagnosi alternative e usare CMR, imaging intracoronarico o test funzionali secondo il sospetto","Concludere subito che non vi è infarto"],"answer":"Escludere diagnosi alternative e usare CMR, imaging intracoronarico o test funzionali secondo il sospetto","displayAnswer":"Escludere diagnosi alternative e usare CMR, imaging intracoronarico o test funzionali secondo il sospetto","explanation":"La figura delle linee guida tratta MINOCA come diagnosi di lavoro. La sequenza varia con STEMI/NSTE-ACS, stabilità e disponibilità dei test.","set":"A"}],"B":[{"id":"q002","source":"1. Vergara -Meccanismi delle aritmie_ automaticità, attività triggerata, rientro - 5 marzo.pdf","page":11,"topic":"Arrhythmia mechanisms","type":"mcq","prompt":"Un circuito anatomico è presente, ma l'impulso si estingue a ogni giro. Quale combinazione manca perché si stabilisca un rientro sostenuto?","options":["Automaticità aumentata e post-potenziali precoci","Depolarizzazione simultanea di tutto il circuito","Blocco bidirezionale e assenza di tessuto eccitabile","Conduzione bidirezionale rapida e periodo refrattario breve","Blocco unidirezionale e conduzione sufficientemente lenta"],"answer":"Blocco unidirezionale e conduzione sufficientemente lenta","displayAnswer":"Blocco unidirezionale e conduzione sufficientemente lenta","explanation":"Il rientro richiede un circuito, un blocco unidirezionale e una conduzione lenta che permetta al tessuto inizialmente refrattario di recuperare. La sola presenza di un percorso chiuso non è sufficiente.","set":"B"},{"id":"q005","source":"1. Vergara -Meccanismi delle aritmie_ automaticità, attività triggerata, rientro - 5 marzo.pdf","page":17,"topic":"Arrhythmia mechanisms","type":"mcq","prompt":"Perché un farmaco che prolunga molto la ripolarizzazione può favorire torsione di punta?","options":["Abbrevia il periodo refrattario ventricolare","Aumenta la probabilità che post-potenziali precoci raggiungano la soglia","Blocca selettivamente la conduzione retrograda nodale","Elimina la dispersione della ripolarizzazione","Sopprime ogni attività dipendente dal calcio"],"answer":"Aumenta la probabilità che post-potenziali precoci raggiungano la soglia","displayAnswer":"Aumenta la probabilità che post-potenziali precoci raggiungano la soglia","explanation":"La ripolarizzazione prolungata facilita post-depolarizzazioni precoci e attività triggerata, terreno per torsione di punta. Non abbrevia la refrattarietà né rende omogenea la ripolarizzazione.","set":"B"},{"id":"q009","source":"10. SPECT e PET nella valutazione di sospetta CAD.pdf","page":1,"topic":"Nuclear cardiology","type":"mcq","prompt":"Osserva lo schema di stratificazione. In un paziente con probabilità clinica molto alta di CAD ostruttiva, quale esame è proposto come passaggio iniziale?","options":["Coronarografia invasiva","PET-FDG per vitalità in tutti i casi","Solo ECG da sforzo","Nessun ulteriore test","Coro-TC come unica opzione"],"answer":"Coronarografia invasiva","displayAnswer":"Coronarografia invasiva","explanation":"Lo schema orienta direttamente alla coronarografia nei pazienti a probabilità molto alta; nei livelli intermedi sono più appropriati test anatomici o funzionali non invasivi.","image":"assets/figures/01-p001.jpg","imageAlt":"Figura di riferimento da 10. SPECT e PET nella valutazione di sospetta CAD.pdf, pagina 1","imagePage":1,"set":"B"},{"id":"q017","source":"11. La Mura Coro-TC e RMN nella CAD.pdf","page":7,"topic":"Cardiac CT and MRI","type":"mcq","prompt":"Un paziente con stent coronarico da 2,5 mm presenta nuova angina. Perché la coro-TC può essere poco affidabile?","options":["Il mezzo di contrasto non raggiunge gli stent","La TC non può visualizzare alcun graft","La restenosi è definita solo dalla frequenza cardiaca","Gli stent piccoli non contengono metallo","Il piccolo diametro e gli artefatti di blooming possono impedire la valutazione del lume"],"answer":"Il piccolo diametro e gli artefatti di blooming possono impedire la valutazione del lume","displayAnswer":"Il piccolo diametro e gli artefatti di blooming possono impedire la valutazione del lume","explanation":"Negli stent <3 mm la risoluzione e il blooming limitano la stima del lume. Stent più grandi e graft sono generalmente più favorevoli alla valutazione TC.","set":"B"},{"id":"q020","source":"11. La Mura Coro-TC e RMN nella CAD.pdf","page":17,"topic":"Cardiac CT and MRI","type":"mcq","prompt":"Dopo STEMI rivascolarizzato, la CMR mostra un'area scura interna a una zona di late enhancement. Cosa suggerisce?","options":["Versamento pericardico","Ischemia inducibile senza necrosi","Ostruzione microvascolare all'interno dell'infarto","Trombo nell'atrio destro","Miocardio completamente normale"],"answer":"Ostruzione microvascolare all'interno dell'infarto","displayAnswer":"Ostruzione microvascolare all'interno dell'infarto","explanation":"La microvascular obstruction appare come nucleo ipo-intenso all'interno del tessuto infartuato con enhancement ed è associata a prognosi sfavorevole.","set":"B"},{"id":"q024","source":"12. Cirillo - Accessi vascolari arteriosi e venosi.pdf","page":3,"topic":"Vascular access safety","type":"mcq","prompt":"Durante una coronarografia il catetere viene manipolato nell'arco aortico. Quale complicanza non locale deve essere tenuta presente?","options":["Iperplasia neointimale immediata","Embolizzazione cerebrovascolare","Esclusivamente trombosi venosa profonda","Sindrome del QT lungo congenita","Solo ematoma del polso"],"answer":"Embolizzazione cerebrovascolare","displayAnswer":"Embolizzazione cerebrovascolare","explanation":"La procedura può mobilizzare materiale aterotrombotico e causare eventi cerebrovascolari. Le complicanze non sono limitate al sito di accesso.","set":"B"},{"id":"q027","source":"13. Giugliano Accessi vascolari diagnosi e gestione delle complicanze dell'accesso.pdf","page":3,"topic":"Vascular access safety","type":"mcq","prompt":"Osserva il confronto tra accesso radiale e femorale. Quale meccanismo spiega soprattutto il beneficio clinico del radiale?","options":["Maggiore diametro disponibile per qualunque dispositivo","Eliminazione di ogni evento ischemico coronarico","Riduzione dei sanguinamenti maggiori e della necessità di trasfusione","Aumento sistematico della dose di contrasto","Assenza completa di occlusione arteriosa"],"answer":"Riduzione dei sanguinamenti maggiori e della necessità di trasfusione","displayAnswer":"Riduzione dei sanguinamenti maggiori e della necessità di trasfusione","explanation":"Il beneficio del radiale è legato soprattutto a meno complicanze emorragiche e trasfusioni, che si associano a prognosi migliore. Non elimina tutti i rischi né consente sempre grandi guaine.","image":"assets/figures/04-p003.jpg","imageAlt":"Figura di riferimento da 13. Giugliano Accessi vascolari diagnosi e gestione delle complicanze dell'accesso.pdf, pagina 3","imagePage":3,"set":"B"},{"id":"q032","source":"14. Bardi Coronarografia- identificazione della CAD ostruttiva.pdf","page":4,"topic":"Coronary angiography","type":"mcq","prompt":"Quale proiezione è particolarmente utile per separare tronco comune e osti di IVA e circonflessa?","options":["Craniale destra estrema per la coronaria destra","Ecografia sottocostale","Proiezione antero-posteriore senza angolazione in ogni caso","Proiezione caudale sinistra (spider view)","Solo laterale destra"],"answer":"Proiezione caudale sinistra (spider view)","displayAnswer":"Proiezione caudale sinistra (spider view)","explanation":"La spider view apre la biforcazione del tronco comune e facilita la valutazione delle lesioni ostiali di IVA e circonflessa.","set":"B"},{"id":"q036","source":"14. Bardi Coronarografia- identificazione della CAD ostruttiva.pdf","page":17,"topic":"Coronary angiography","type":"mcq","prompt":"Una coronaria diffusamente calcifica presenta un tratto che sembra occluso. Quale limite della sola angiografia deve essere ricordato?","options":["Esclude la necessità di imaging intravascolare","Misura direttamente l'IMR","Mostra il lume, ma caratterizza poco placca, calcio e parete vasale","Distingue sempre vero e falso lume","Quantifica la vitalità miocardica"],"answer":"Mostra il lume, ma caratterizza poco placca, calcio e parete vasale","displayAnswer":"Mostra il lume, ma caratterizza poco placca, calcio e parete vasale","explanation":"L'angiografia è una luminografia. IVUS o OCT possono chiarire morfologia, distribuzione del calcio, espansione dello stent e meccanismo dell'insuccesso.","set":"B"},{"id":"q040","source":"16. Piccolo Rivascolarizzazione nel paziente con disfunzione ventricolare sinistra.pdf","page":6,"topic":"Revascularization and LV dysfunction","type":"mcq","prompt":"Quale sequenza descrive meglio la transizione da ischemia cronica a disfunzione ventricolare persistente?","options":["Episodi ripetuti di stunning possono favorire rimodellamento e perdita progressiva di funzione","La rivascolarizzazione rende automaticamente normale ogni segmento","La CAD non modifica il rimodellamento","Lo stunning è sempre necrosi transmurale immediata","Ogni episodio ischemico aumenta permanentemente la contrattilità"],"answer":"Episodi ripetuti di stunning possono favorire rimodellamento e perdita progressiva di funzione","displayAnswer":"Episodi ripetuti di stunning possono favorire rimodellamento e perdita progressiva di funzione","explanation":"Lo stunning ripetitivo e l'ibernazione possono precedere rimodellamento e fibrosi. La reversibilità dipende da vitalità, estensione della cicatrice e carico ischemico.","set":"B"},{"id":"q043","source":"16. Piccolo Rivascolarizzazione nel paziente con disfunzione ventricolare sinistra.pdf","page":16,"topic":"Revascularization and LV dysfunction","type":"mcq","prompt":"In una malattia multivasale complessa con bassa FE, quale elemento favorisce una discussione Heart Team anziché scegliere automaticamente PCI?","options":["La possibilità di evitare ogni terapia medica","L'assenza di onde P","La presenza di un accesso radiale","Il solo valore della troponina normale","Possibile vantaggio di completezza e durata del CABG, bilanciato con rischio chirurgico e preferenze"],"answer":"Possibile vantaggio di completezza e durata del CABG, bilanciato con rischio chirurgico e preferenze","displayAnswer":"Possibile vantaggio di completezza e durata del CABG, bilanciato con rischio chirurgico e preferenze","explanation":"La scelta richiede anatomia, rischio operatorio, diabete, comorbilità, possibilità di rivascolarizzazione completa e obiettivi del paziente; non esiste una risposta basata su un solo parametro.","set":"B"},{"id":"q047","source":"17. Ass. Pilato Rivascolarizzazione miocardica chirurgica.pdf","page":3,"topic":"Surgical revascularization","type":"mcq","prompt":"Perché un paziente diabetico con coronaropatia diffusa può essere favorito dal CABG rispetto a una strategia focale?","options":["La PCI non può mai essere eseguita nel diabete","I graft possono bypassare più segmenti malati e offrire protezione oltre le singole stenosi trattate","Il CABG rimuove tutta l'aterosclerosi","Il diabete impedisce sempre l'uso di arterie mammarie","La chirurgia elimina la necessità di prevenzione secondaria"],"answer":"I graft possono bypassare più segmenti malati e offrire protezione oltre le singole stenosi trattate","displayAnswer":"I graft possono bypassare più segmenti malati e offrire protezione oltre le singole stenosi trattate","explanation":"Nella malattia diffusa, una strategia di bypass può ottenere maggiore completezza e proteggere territori distali; la decisione resta individuale e multidisciplinare.","set":"B"},{"id":"q051","source":"17. Ass. Pilato Rivascolarizzazione miocardica chirurgica.pdf","page":1,"topic":"Surgical revascularization","type":"mcq","prompt":"Qual è il principale obiettivo tecnico di un CABG ben pianificato?","options":["Sostituire la funzione del ventricolo destro","Aumentare il numero di anastomosi indipendentemente dal territorio","Portare flusso adeguato a miocardio vitale oltre stenosi significative con graft durevoli","Occludere intenzionalmente tutti i vasi nativi","Eliminare ogni necessità di controllo dei fattori di rischio"],"answer":"Portare flusso adeguato a miocardio vitale oltre stenosi significative con graft durevoli","displayAnswer":"Portare flusso adeguato a miocardio vitale oltre stenosi significative con graft durevoli","explanation":"Il valore del CABG dipende da target, qualità dei condotti, flusso competitivo, territorio vitale e durata. Il numero di graft non è un obiettivo isolato.","set":"B"},{"id":"q055","source":"18. Piccolo Rivascolarizzazione miocardica nelle sindromi coronariche acute.pdf","page":17,"topic":"ACS revascularization","type":"mcq","prompt":"In uno STEMI multivasale stabile, perché la rivascolarizzazione completa delle lesioni non culprit può essere programmata precocemente?","options":["Perché la lesione culprit non va trattata","Perché ogni stenosi angiografica deve essere trattata senza valutazione","Perché il rischio è esclusivamente emorragico","Riduce eventi futuri legati a stenosi prognosticamente rilevanti oltre la culprit","Per evitare la terapia medica"],"answer":"Riduce eventi futuri legati a stenosi prognosticamente rilevanti oltre la culprit","displayAnswer":"Riduce eventi futuri legati a stenosi prognosticamente rilevanti oltre la culprit","explanation":"Nei pazienti stabili, evidenze sostengono una strategia completa selezionata. Anatomia, fisiologia e timing guidano il trattamento delle non culprit.","set":"B"},{"id":"q058","source":"18. Piccolo Rivascolarizzazione miocardica nelle sindromi coronariche acute.pdf","page":27,"topic":"ACS revascularization","type":"mcq","prompt":"Perché una CTO presente durante una SCA non deve essere automaticamente considerata una lesione acuta da trattare subito?","options":["Una CTO è sempre la culprit","Il trattamento non richiede mai contrasto","Può essere cronica, con collaterali e complessità procedurale non giustificata nella fase acuta","Le CTO non influenzano mai la prognosi","La CTO scompare con eparina"],"answer":"Può essere cronica, con collaterali e complessità procedurale non giustificata nella fase acuta","displayAnswer":"Può essere cronica, con collaterali e complessità procedurale non giustificata nella fase acuta","explanation":"Occorre distinguere la culprit acuta dalla malattia cronica. La CTO può essere valutata in modo differito sulla base di sintomi, vitalità, ischemia e fattibilità.","set":"B"},{"id":"q062","source":"19. Piccolo Shock cardiogeno - rivascolarizzazione e supporto al circolo.pdf","page":14,"topic":"Cardiogenic shock","type":"mcq","prompt":"Qual è il razionale dell'associazione ECPELLA?","options":["Aumentare ulteriormente il postcarico senza drenaggio","Trattare esclusivamente una bradicardia","Eliminare ogni necessità di monitoraggio","Combinare supporto sistemico ECMO con unloading del ventricolo sinistro mediante Impella","Sostituire l'ECMO con un pacemaker"],"answer":"Combinare supporto sistemico ECMO con unloading del ventricolo sinistro mediante Impella","displayAnswer":"Combinare supporto sistemico ECMO con unloading del ventricolo sinistro mediante Impella","explanation":"L'Impella può decomprimere il ventricolo sinistro durante ECMO VA, limitando distensione e congestione. L'associazione aumenta però complessità e complicanze.","set":"B"},{"id":"q066","source":"2. Strisciuglio - Lo studio elettrofisiologico_ indicazioni, tecnica di esecuzione, parametri registrati - 5 marzo.pdf","page":22,"topic":"Electrophysiology","type":"mcq","prompt":"Osserva le diverse mappe elettroanatomiche. Perché si combinano mappe di attivazione, voltaggio e anatomia?","options":["Per diagnosticare esclusivamente stenosi valvolari","Per calcolare il calcio coronarico","Per collegare il timing elettrico al substrato e localizzare il target di ablazione","Per sostituire ogni elettrogramma intracavitario","Per misurare la perfusione miocardica"],"answer":"Per collegare il timing elettrico al substrato e localizzare il target di ablazione","displayAnswer":"Per collegare il timing elettrico al substrato e localizzare il target di ablazione","explanation":"Ogni mappa risponde a una domanda diversa: l'attivazione descrive la sequenza, il voltaggio il substrato e l'anatomia i rapporti spaziali.","image":"assets/figures/10-p022.jpg","imageAlt":"Figura di riferimento da 2. Strisciuglio - Lo studio elettrofisiologico_ indicazioni, tecnica di esecuzione, parametri registrati - 5 marzo.pdf, pagina 22","imagePage":22,"set":"B"},{"id":"q071","source":"2. Strisciuglio - Lo studio elettrofisiologico_ indicazioni, tecnica di esecuzione, parametri registrati - 5 marzo.pdf","page":16,"topic":"Electrophysiology","type":"mcq","prompt":"Quale osservazione durante una tachicardia regolare aiuta a distinguere AVRT da AVNRT?","options":["La pressione arteriosa isolata","Il solo colore della mappa","La sequenza e il tempo di attivazione atriale retrograda, insieme alla risposta al pacing ventricolare","Il valore di LDL","La presenza di calcio coronarico"],"answer":"La sequenza e il tempo di attivazione atriale retrograda, insieme alla risposta al pacing ventricolare","displayAnswer":"La sequenza e il tempo di attivazione atriale retrograda, insieme alla risposta al pacing ventricolare","explanation":"La relazione VA e le manovre di entrainment/pacing chiariscono se il ventricolo e una via accessoria partecipano al circuito.","set":"B"},{"id":"q075","source":"20. Di Serafino Fisiologia coronarica nel paziente candidato a rivascolarizzazione coronarica; ANOCA e INOCA.pdf","page":6,"topic":"Coronary physiology and INOCA","type":"mcq","prompt":"Durante pullback FFR il valore aumenta gradualmente senza un singolo salto. Quale pattern suggerisce?","options":["Vasospasmo certo","Singola stenosi focale","Malattia epicardica diffusa","Errore obbligato del sensore","Assenza totale di malattia"],"answer":"Malattia epicardica diffusa","displayAnswer":"Malattia epicardica diffusa","explanation":"Una perdita di pressione distribuita lungo il vaso produce una risalita graduale. Una stenosi focale genera invece un drop localizzato.","set":"B"},{"id":"q079","source":"20. Di Serafino Fisiologia coronarica nel paziente candidato a rivascolarizzazione coronarica; ANOCA e INOCA.pdf","page":4,"topic":"Coronary physiology and INOCA","type":"mcq","prompt":"Una stenosi intermedia ha FFR non ischemico. Qual è la strategia coerente con la fisiologia?","options":["CABG urgente","Diagnosticare automaticamente MINOCA","Stent obbligatorio per qualunque stenosi visibile","Interrompere la prevenzione secondaria","Differire la PCI e ottimizzare terapia e valutazione clinica"],"answer":"Differire la PCI e ottimizzare terapia e valutazione clinica","displayAnswer":"Differire la PCI e ottimizzare terapia e valutazione clinica","explanation":"Quando FFR esclude ischemia attribuibile alla lesione, il trattamento differito ha esiti favorevoli; restano indicati controllo dei sintomi e dei fattori di rischio.","set":"B"},{"id":"q083","source":"23. Di Seraf.  MINOCA (by giovanni vitale.pdf","page":4,"topic":"MINOCA","type":"mcq","prompt":"Perché la CMR dovrebbe essere eseguita precocemente nel sospetto MINOCA?","options":["Dopo 24 ore il gadolinio non entra nel miocardio","Edema e pattern tissutali diagnostici possono attenuarsi con il tempo","La CMR precoce sostituisce sempre OCT e test funzionali","La CMR visualizza soltanto calcio coronarico","Serve solo a misurare la pressione aortica"],"answer":"Edema e pattern tissutali diagnostici possono attenuarsi con il tempo","displayAnswer":"Edema e pattern tissutali diagnostici possono attenuarsi con il tempo","explanation":"Una CMR tempestiva aumenta la probabilità di distinguere infarto, miocardite e Takotsubo. Può essere completata da imaging intracoronarico e test vasomotori.","set":"B"},{"id":"q086","source":"23. Di Seraf.  MINOCA (by giovanni vitale.pdf","page":5,"topic":"MINOCA","type":"mcq","prompt":"In una SCAD gestita conservativamente, perché la DAPT prolungata non va applicata automaticamente come dopo stent?","options":["Non è presente uno stent e il bilancio tra trombosi e sanguinamento intramurale è diverso","Le piastrine non partecipano mai alle SCA","SCAD è sempre una placca aterosclerotica","L'aspirina è sempre vietata","La terapia conservativa richiede anticoagulazione tripla"],"answer":"Non è presente uno stent e il bilancio tra trombosi e sanguinamento intramurale è diverso","displayAnswer":"Non è presente uno stent e il bilancio tra trombosi e sanguinamento intramurale è diverso","explanation":"La terapia antiplatelet nella SCAD non trattata con PCI deve essere personalizzata; l'evidenza è osservazionale e il meccanismo non coincide con la rottura di placca classica.","set":"B"},{"id":"q090","source":"23. MINOCA, MANCA SIA LEZ CHE SBOB.pdf","page":12,"topic":"Procedural safety","type":"mcq","prompt":"Una CTO calcifica e tortuosa richiede dispositivi più grandi. Quale principio va applicato alla scelta dell'accesso?","options":["Bilanciare supporto e calibro necessari con il rischio vascolare ed emorragico","Usare sempre il radiale anche se il dispositivo non passa","Ignorare imaging del sito di puntura","Usare sempre il femorale indipendentemente dal caso","Scegliere in base alla sola preferenza estetica"],"answer":"Bilanciare supporto e calibro necessari con il rischio vascolare ed emorragico","displayAnswer":"Bilanciare supporto e calibro necessari con il rischio vascolare ed emorragico","explanation":"La complessità può richiedere più supporto, ma l'accesso va individualizzato secondo anatomia, device, esperienza e rischio di sanguinamento.","set":"B"},{"id":"q094","source":"25-26 Franzone - Terapia medica ottimale nelle sindromi coronariche acute e croniche.pdf","page":7,"topic":"Antiplatelet and medical therapy","type":"mcq","prompt":"Un paziente soddisfa criteri HBR dopo PCI non complicata. Quale modifica può essere ragionevole?","options":["Sospendere tutti i farmaci il giorno della PCI","Aggiungere anticoagulante senza indicazione","Accorciare la DAPT e proseguire una strategia antiplatelet semplificata se clinicamente appropriato","Raddoppiare la dose di aspirina","Prolungare sempre DAPT oltre tre anni"],"answer":"Accorciare la DAPT e proseguire una strategia antiplatelet semplificata se clinicamente appropriato","displayAnswer":"Accorciare la DAPT e proseguire una strategia antiplatelet semplificata se clinicamente appropriato","explanation":"Nei pazienti ad alto rischio emorragico, trial con DAPT abbreviata mostrano meno sanguinamento con protezione ischemica accettabile in selezionati.","set":"B"},{"id":"q098","source":"25-26 Franzone - Terapia medica ottimale nelle sindromi coronariche acute e croniche.pdf","page":23,"topic":"Antiplatelet and medical therapy","type":"mcq","prompt":"Un paziente con fibrillazione atriale necessita di OAC dopo PCI. Qual è il principio generale per ridurre sanguinamento?","options":["Usare due anticoagulanti","Limitare la triplice terapia e passare appena possibile a OAC più un singolo antiaggregante","Mantenere triplice terapia indefinitamente","Aumentare l'aspirina oltre 300 mg","Sospendere l'OAC nonostante alto rischio embolico"],"answer":"Limitare la triplice terapia e passare appena possibile a OAC più un singolo antiaggregante","displayAnswer":"Limitare la triplice terapia e passare appena possibile a OAC più un singolo antiaggregante","explanation":"La durata della triplice terapia deve essere la minima compatibile con il rischio ischemico; poi si semplifica, spesso con clopidogrel come singolo antiaggregante.","set":"B"},{"id":"q102","source":"28. Cirillo Terapia antitrombotica nelle sindromi coronariche acute - dal pretrattamento alla dimissione.pdf","page":12,"topic":"Antithrombotic therapy","type":"mcq","prompt":"Dopo 12 mesi senza eventi, quando può essere considerata una DAPT prolungata?","options":["Quando il rischio emorragico è estremo","Per trattare la fibrillazione atriale da sola","In ogni paziente indipendentemente dal sanguinamento","Solo se non è stato impiantato uno stent","Quando il rischio ischemico residuo è alto e il rischio emorragico accettabile"],"answer":"Quando il rischio ischemico residuo è alto e il rischio emorragico accettabile","displayAnswer":"Quando il rischio ischemico residuo è alto e il rischio emorragico accettabile","explanation":"La durata è un bilancio dinamico. Pregresso infarto, PCI complessa e malattia diffusa possono favorire estensione; HBR orienta alla semplificazione.","set":"B"},{"id":"q106","source":"28. Cirillo Terapia antitrombotica nelle sindromi coronariche acute - dal pretrattamento alla dimissione.pdf","page":2,"topic":"Antithrombotic therapy","type":"mcq","prompt":"Qual è la funzione principale dell'anticoagulante parenterale durante PCI per SCA?","options":["Sciogliere ogni placca calcifica","Trattare la disfunzione microvascolare cronica","Limitare la generazione di trombina e la trombosi legata a cateteri e procedura","Ridurre direttamente LDL","Sostituire completamente gli antiaggreganti"],"answer":"Limitare la generazione di trombina e la trombosi legata a cateteri e procedura","displayAnswer":"Limitare la generazione di trombina e la trombosi legata a cateteri e procedura","explanation":"Anticoagulanti e antiaggreganti agiscono su componenti diverse della trombosi e vengono combinati nella fase procedurale con attenzione al sanguinamento.","set":"B"},{"id":"q110","source":"3. Rapacciuolo - Disfunzione del nodo del seno e del nodo AV- fisiopatologia, test diagnostici, trattamento.pdf","page":6,"topic":"Bradyarrhythmias","type":"mcq","prompt":"Un paziente presenta BAV avanzato esclusivamente durante il sonno e russamento importante. Quale valutazione è prioritaria?","options":["PET di vitalità","Screening per apnea ostruttiva del sonno","OCT coronarica","Ablazione AVNRT","Test all'acetilcolina"],"answer":"Screening per apnea ostruttiva del sonno","displayAnswer":"Screening per apnea ostruttiva del sonno","explanation":"OSAS può causare bradiaritmie notturne potenzialmente reversibili con trattamento respiratorio. Il pacemaker non va deciso senza considerare il contesto.","set":"B"},{"id":"q113","source":"3. Rapacciuolo - Disfunzione del nodo del seno e del nodo AV- fisiopatologia, test diagnostici, trattamento.pdf","page":18,"topic":"Bradyarrhythmias","type":"mcq","prompt":"Dopo infarto inferiore compare BAV completo con instabilità. Qual è la priorità?","options":["Rivascolarizzazione e supporto temporaneo della frequenza se necessario","Solo osservazione senza monitoraggio","Sospensione della riperfusione","Ablazione del nodo AV","Impianto immediato definitivo in ogni caso"],"answer":"Rivascolarizzazione e supporto temporaneo della frequenza se necessario","displayAnswer":"Rivascolarizzazione e supporto temporaneo della frequenza se necessario","explanation":"Il BAV ischemico può regredire dopo riperfusione, soprattutto nell'infarto inferiore. Stabilizzazione e rivascolarizzazione precedono la decisione definitiva.","set":"B"},{"id":"q115","source":"31. Spaccarotella Dissezioni Coronariche Spontanee (1).pdf","page":13,"topic":"SCAD","type":"mcq","prompt":"Osserva l'algoritmo diagnostico-terapeutico. In una SCAD stabile con flusso conservato, quale strategia è generalmente preferita?","options":["CABG in ogni caso","Gestione conservativa con monitoraggio","Fibrinolisi sistematica","PCI obbligatoria di tutta la dissezione","Nessun follow-up"],"answer":"Gestione conservativa con monitoraggio","displayAnswer":"Gestione conservativa con monitoraggio","explanation":"Molte SCAD guariscono spontaneamente. PCI può essere tecnicamente difficile e viene riservata a ischemia persistente, instabilità o anatomie ad alto rischio.","image":"assets/figures/17-p013.jpg","imageAlt":"Figura di riferimento da 31. Spaccarotella Dissezioni Coronariche Spontanee (1).pdf, pagina 13","imagePage":13,"set":"B"},{"id":"q122","source":"31. Spaccarotella Dissezioni Coronariche Spontanee (1).pdf","page":17,"topic":"SCAD","type":"mcq","prompt":"Perché la terapia standard della SCA non può essere trasferita integralmente alla SCAD?","options":["SCAD non causa mai infarto","Il follow-up non serve","I beta-bloccanti sono sempre controindicati","Le piastrine sono sempre irrilevanti","Il meccanismo è separazione della parete/ematoma, non necessariamente rottura di placca aterotrombotica"],"answer":"Il meccanismo è separazione della parete/ematoma, non necessariamente rottura di placca aterotrombotica","displayAnswer":"Il meccanismo è separazione della parete/ematoma, non necessariamente rottura di placca aterotrombotica","explanation":"Farmaci antitrombotici e rivascolarizzazione vanno personalizzati. La gestione deve rispettare il meccanismo non aterosclerotico e il rischio di estensione.","set":"B"},{"id":"q126","source":"32. Losi - complicanze meccaniche dell' infarto.pdf","page":8,"topic":"Mechanical complications of MI","type":"mcq","prompt":"Quale reperto emodinamico è tipico di una rottura del setto post-infartuale?","options":["Conduzione AV accelerata","Gradiente aortico fisso","Shunt sinistro-destro con step-up di saturazione nel ventricolo destro","Riduzione isolata dell'IMR","Assenza di flusso tra ventricoli"],"answer":"Shunt sinistro-destro con step-up di saturazione nel ventricolo destro","displayAnswer":"Shunt sinistro-destro con step-up di saturazione nel ventricolo destro","explanation":"Il difetto crea passaggio di sangue ossigenato dal ventricolo sinistro al destro, sovraccarico polmonare e shock. Doppler e cateterismo possono documentarlo.","set":"B"},{"id":"q130","source":"4. Pergola - Short QT, Long QT, TV idiopatica.pdf","page":22,"topic":"Inherited repolarization disorders","type":"mcq","prompt":"Osserva la tabella di terapia. Perché nadololo o propranololo sono spesso preferiti nella LQTS?","options":["Sono privi di bradicardia","Eliminano ogni necessità di stratificazione","Offrono un beta-blocco non selettivo efficace nel ridurre trigger adrenergici","Accorciano il QT bloccando direttamente il sodio in tutti","Trattano la via accessoria"],"answer":"Offrono un beta-blocco non selettivo efficace nel ridurre trigger adrenergici","displayAnswer":"Offrono un beta-blocco non selettivo efficace nel ridurre trigger adrenergici","explanation":"Il beta-blocco riduce eventi adrenergici, con efficacia non identica tra molecole. Aderenza, genotipo e profilo clinico guidano la scelta.","image":"assets/figures/19-p022.jpg","imageAlt":"Figura di riferimento da 4. Pergola - Short QT, Long QT, TV idiopatica.pdf, pagina 22","imagePage":22,"set":"B"},{"id":"q135","source":"4. Pergola - Short QT, Long QT, TV idiopatica.pdf","page":27,"topic":"Inherited repolarization disorders","type":"mcq","prompt":"Perché la stratificazione del rischio nella LQTS deve essere aggiornata nel tempo?","options":["Il genotipo cambia ogni anno","Il primo ECG predice perfettamente la vita intera","Il beta-blocco elimina ogni evento","Il rischio è identico per tutti","Sintomi, aderenza, QT, età e circostanze degli eventi possono cambiare"],"answer":"Sintomi, aderenza, QT, età e circostanze degli eventi possono cambiare","displayAnswer":"Sintomi, aderenza, QT, età e circostanze degli eventi possono cambiare","explanation":"La valutazione è longitudinale: nuovi episodi o variazioni cliniche possono modificare intensità terapeutica e indicazione a device/simpaticectomia.","set":"B"},{"id":"q139","source":"5. Rapacciuolo prevenzione SCD + dispositivi per HF 2.pdf","page":1,"topic":"Sudden cardiac death and devices","type":"mcq","prompt":"Perché la defibrillazione precoce è determinante nell'arresto da FV?","options":["La FV si converte sempre spontaneamente","Il danno cerebrale non dipende dal tempo","La probabilità di successo diminuisce rapidamente con il tempo senza shock","La RCP sostituisce definitivamente lo shock","L'ossigeno da solo interrompe il circuito"],"answer":"La probabilità di successo diminuisce rapidamente con il tempo senza shock","displayAnswer":"La probabilità di successo diminuisce rapidamente con il tempo senza shock","explanation":"RCP mantiene una perfusione minima, ma la FV richiede defibrillazione. Accesso pubblico ai DAE e catena del soccorso riducono il ritardo.","set":"B"},{"id":"q142","source":"5. Rapacciuolo prevenzione SCD + dispositivi per HF 2.pdf","page":9,"topic":"Sudden cardiac death and devices","type":"mcq","prompt":"Un paziente con ICD ha ripetute TV monomorfe terminate da ATP. Quale strategia può ridurre recidive e terapie del device?","options":["Ablazione transcatetere del substrato aritmico in pazienti appropriati","Impiantare un secondo ICD","Somministrare solo aspirina","Disattivare ogni terapia ICD","Eseguire sempre CABG"],"answer":"Ablazione transcatetere del substrato aritmico in pazienti appropriati","displayAnswer":"Ablazione transcatetere del substrato aritmico in pazienti appropriati","explanation":"L'ATP tratta gli episodi ma non elimina il circuito. L'ablazione può ridurre burden e shock, mantenendo l'ICD come protezione.","set":"B"},{"id":"q147","source":"5. Vergara -CRT e ICD Trial Clinici-.pdf","page":14,"topic":"Cardiac resynchronization therapy","type":"mcq","prompt":"Qual è il meccanismo terapeutico della CRT nello scompenso con LBBB?","options":["Ridurre direttamente LDL","Bloccare il flusso aortico","Aumentare la trombosi coronarica","Risincronizzare l'attivazione dei ventricoli per migliorare efficienza e rimodellamento","Creare una via accessoria"],"answer":"Risincronizzare l'attivazione dei ventricoli per migliorare efficienza e rimodellamento","displayAnswer":"Risincronizzare l'attivazione dei ventricoli per migliorare efficienza e rimodellamento","explanation":"Stimolazione coordinata può ridurre dissincronia meccanica, rigurgito mitralico funzionale e consumo inefficiente di energia.","set":"B"},{"id":"q150","source":"6 Strisciugno Sincope.pdf","page":7,"topic":"Syncope","type":"mcq","prompt":"Osserva le indicazioni allo studio elettrofisiologico. Quale paziente trae più beneficio dal SEF?","options":["Sincope inspiegata con blocco di branca e sospetta malattia del sistema di conduzione","Caduta meccanica osservata","Ipotensione da disidratazione già dimostrata","Sincope vasovagale tipica con prodromi e ECG normale","Vertigine posizionale"],"answer":"Sincope inspiegata con blocco di branca e sospetta malattia del sistema di conduzione","displayAnswer":"Sincope inspiegata con blocco di branca e sospetta malattia del sistema di conduzione","explanation":"Il SEF è utile quando la probabilità pre-test di causa aritmica e infra-Hisiana è significativa. Nei casi rari e a basso rischio può essere preferito monitoraggio prolungato.","image":"assets/figures/22-p007.jpg","imageAlt":"Figura di riferimento da 6 Strisciugno Sincope.pdf, pagina 7","imagePage":7,"set":"B"},{"id":"q156","source":"6 Strisciugno Sincope.pdf","page":9,"topic":"Syncope","type":"mcq","prompt":"Qual è l'evento iniziale tipico della sincope riflessa durante prolungata stazione eretta?","options":["Riduzione del ritorno venoso con risposta autonomica inappropriata","Attivazione di una via accessoria","Aumento persistente delle resistenze","Aumento stabile del precarico","Occlusione coronarica obbligata"],"answer":"Riduzione del ritorno venoso con risposta autonomica inappropriata","displayAnswer":"Riduzione del ritorno venoso con risposta autonomica inappropriata","explanation":"Il minor riempimento può innescare vasodilatazione e/o bradicardia riflesse, causando ipoperfusione cerebrale transitoria.","set":"B"},{"id":"q160","source":"6. Strisciuglio Wolff Parkinson White.pdf","page":4,"topic":"WPW and accessory pathways","type":"mcq","prompt":"Quale proprietà della via accessoria indica maggiore rischio durante fibrillazione atriale?","options":["Blocco anterogrado completo","Lungo periodo refrattario","Periodo refrattario anterogrado molto breve, con intervalli RR preeccitati brevi","Assenza di preeccitazione durante pacing atriale","Conduzione solo retrograda"],"answer":"Periodo refrattario anterogrado molto breve, con intervalli RR preeccitati brevi","displayAnswer":"Periodo refrattario anterogrado molto breve, con intervalli RR preeccitati brevi","explanation":"Una via che recupera rapidamente può trasmettere molti impulsi atriali ai ventricoli. Il rischio non dipende solo dalla presenza visiva dell'onda delta.","set":"B"},{"id":"q163","source":"6. Strisciuglio Wolff Parkinson White.pdf","page":8,"topic":"WPW and accessory pathways","type":"mcq","prompt":"Durante pacing atriale, il QRS passa bruscamente da largo preeccitato a stretto. Che cosa è stato raggiunto?","options":["Il periodo refrattario anterogrado della via accessoria","Il blocco seno-atriale","Il periodo refrattario del ventricolo destro","La CFR massima","La soglia di fibrillazione"],"answer":"Il periodo refrattario anterogrado della via accessoria","displayAnswer":"Il periodo refrattario anterogrado della via accessoria","explanation":"Quando la via accessoria non conduce più, l'attivazione passa prevalentemente dal nodo AV-His e il QRS perde la preeccitazione.","set":"B"},{"id":"q167","source":"7. Vergara Tachicardia da rientro nodale 2.pdf","page":1,"topic":"AVNRT","type":"mcq","prompt":"Perché l'AVNRT può iniziare dopo un'extrasistole atriale?","options":["Si apre una coronaria occlusa","Il nodo del seno conduce retrogradamente","L'extrasistole elimina ogni differenza di refrattarietà","La via rapida può essere refrattaria mentre la via lenta conduce, creando il circuito di rientro","Il ventricolo diventa un pacemaker automatico"],"answer":"La via rapida può essere refrattaria mentre la via lenta conduce, creando il circuito di rientro","displayAnswer":"La via rapida può essere refrattaria mentre la via lenta conduce, creando il circuito di rientro","explanation":"La dissociazione funzionale delle due vie permette blocco unidirezionale sulla rapida e ritorno retrogrado dopo recupero.","set":"B"},{"id":"q170","source":"7. Vergara Tachicardia da rientro nodale 2.pdf","page":19,"topic":"AVNRT","type":"mcq","prompt":"Qual è il target usuale dell'ablazione nell'AVNRT?","options":["Ablazione del nodo del seno","Isolamento di tutte le vene polmonari","Ablazione completa del fascio di His","Modificazione della via lenta nella regione posteroseptale","Stent della coronaria destra"],"answer":"Modificazione della via lenta nella regione posteroseptale","displayAnswer":"Modificazione della via lenta nella regione posteroseptale","explanation":"Si mira a eliminare o rendere non inducibile il circuito preservando la conduzione AV. L'ablazione vicino al His aumenterebbe il rischio di blocco.","set":"B"},{"id":"q174","source":"8. Vergara Sindromi Genetiche Vergara (Brugada, ER, CPVT) 2.pdf","page":2,"topic":"Inherited arrhythmia syndromes","type":"mcq","prompt":"Quale pattern ECG è diagnostico per la sindrome di Brugada nel contesto appropriato?","options":["Sottoslivellamento diffuso ST","Solo pattern saddleback tipo 2","QTc lungo isolato","Onda delta","Pattern tipo 1 coved nelle derivazioni precordiali destre"],"answer":"Pattern tipo 1 coved nelle derivazioni precordiali destre","displayAnswer":"Pattern tipo 1 coved nelle derivazioni precordiali destre","explanation":"Il tipo 1 è il pattern diagnostico; i pattern tipo 2/3 sono sospetti e possono richiedere posizionamento alto delle derivazioni o test farmacologico.","set":"B"},{"id":"q178","source":"8. Vergara Sindromi Genetiche Vergara (Brugada, ER, CPVT) 2.pdf","page":24,"topic":"Inherited arrhythmia syndromes","type":"mcq","prompt":"In quali pazienti con Brugada può essere considerata l'ablazione del substrato epicardico?","options":["In casi selezionati con eventi ventricolari ricorrenti o tempesta aritmica nonostante terapia","Per trattare l'ipertensione","Per sostituire la diagnosi","Per eliminare una stenosi coronarica","In ogni portatore asintomatico"],"answer":"In casi selezionati con eventi ventricolari ricorrenti o tempesta aritmica nonostante terapia","displayAnswer":"In casi selezionati con eventi ventricolari ricorrenti o tempesta aritmica nonostante terapia","explanation":"L'ablazione mira al substrato aritmogeno del tratto di efflusso destro; è procedura specialistica, non screening universale.","set":"B"},{"id":"q182","source":"9. Ciampi Ecostress.pdf","page":2,"topic":"Stress echocardiography","type":"mcq","prompt":"Quale stressore è più adatto quando l'obiettivo principale è valutare riserva contrattile e cinetica?","options":["Solo nitrato","Dobutamina, se non controindicata","Atropina isolata in tutti","Adenosina per aumentare direttamente la contrattilità","Nessuno stress"],"answer":"Dobutamina, se non controindicata","displayAnswer":"Dobutamina, se non controindicata","explanation":"La dobutamina aumenta inotropismo e cronotropismo. I vasodilatatori sono particolarmente utili per perfusione e riserva di flusso.","set":"B"},{"id":"q185","source":"9. Ciampi Ecostress.pdf","page":15,"topic":"Stress echocardiography","type":"mcq","prompt":"Un paziente iperteso ha flusso coronarico basale elevato e rapporto iperemia/riposo ridotto. Quale cautela interpretativa è necessaria?","options":["L'ipertensione aumenta sempre la CFR","Una CFR bassa indica sempre stenosi focale","Il flusso basale non entra nel rapporto","Il valore non ha relazione con emodinamica","La CFR può ridursi perché il denominatore è alto, non solo perché il flusso iperemico è basso"],"answer":"La CFR può ridursi perché il denominatore è alto, non solo perché il flusso iperemico è basso","displayAnswer":"La CFR può ridursi perché il denominatore è alto, non solo perché il flusso iperemico è basso","explanation":"La riserva è un rapporto. Frequenza, pressione e domanda basale influenzano il denominatore e vanno integrati nell'interpretazione.","set":"B"},{"id":"q189","source":"Lezione Gargiulo 2026.pdf","page":1,"topic":"ACS risk and antithrombotic strategy","type":"mcq","prompt":"Osserva i criteri di alto rischio ischemico. Quale principio deve guidare una DAPT prolungata?","options":["Ignorare età e sanguinamenti","Beneficio ischemico atteso superiore al rischio emorragico individuale","Decisione basata solo sul numero di stent","Usare sempre triplice terapia","Prolungamento automatico dopo ogni PCI"],"answer":"Beneficio ischemico atteso superiore al rischio emorragico individuale","displayAnswer":"Beneficio ischemico atteso superiore al rischio emorragico individuale","explanation":"PCI complessa e malattia diffusa aumentano il rischio ischemico, ma la durata va bilanciata con ARC-HBR, storia emorragica e comorbilità.","image":"assets/figures/27-p001.jpg","imageAlt":"Figura di riferimento da Lezione Gargiulo 2026.pdf, pagina 1","imagePage":1,"set":"B"},{"id":"q196","source":"Lezione Gargiulo 2026.pdf","page":32,"topic":"Mechanical circulatory support","type":"mcq","prompt":"In un paziente con Impella compare allarme di suzione. Quale causa va cercata per prima?","options":["Aumento della CFR","Trombosi venosa superficiale","Iperperfusione cerebrale","QT lungo","Basso precarico, malposizionamento o insufficienza ventricolare destra"],"answer":"Basso precarico, malposizionamento o insufficienza ventricolare destra","displayAnswer":"Basso precarico, malposizionamento o insufficienza ventricolare destra","explanation":"La pompa aspira quando manca volume in ingresso o la posizione è errata. Ecografia ed emodinamica guidano correzione; RCP e defibrillazione restano possibili.","set":"B"},{"id":"q200","source":"guidelines 2023-SCA.pdf","page":69,"topic":"ACS guidelines","type":"mcq","prompt":"Dopo ACS con LVEF ≤40%, quale terapia ha indicazione prognostica indipendentemente dai sintomi di scompenso?","options":["Antibiotico cronico","Beta-bloccante, insieme alla terapia modificante la prognosi appropriata","Aspirina ad alte dosi come unica terapia","Nessun trattamento se asintomatico","Solo nitrato al bisogno"],"answer":"Beta-bloccante, insieme alla terapia modificante la prognosi appropriata","displayAnswer":"Beta-bloccante, insieme alla terapia modificante la prognosi appropriata","explanation":"Le linee guida raccomandano beta-blocco nella ridotta FE e RAAS-inibizione in presenza di FE ridotta, scompenso o comorbilità indicate, oltre alla prevenzione lipidica.","set":"B"}],"C":[{"id":"q003","source":"1. Vergara -Meccanismi delle aritmie_ automaticità, attività triggerata, rientro - 5 marzo.pdf","page":5,"topic":"Arrhythmia mechanisms","type":"mcq","prompt":"Quale modifica di una cellula pacemaker aumenta più direttamente la frequenza di scarica spontanea?","options":["Un prolungamento isolato della fase 2 ventricolare","Un potenziale soglia più positivo e lontano","Un potenziale di riposo più negativo senza altre variazioni","Una riduzione della pendenza di fase 4","Un aumento della pendenza della depolarizzazione di fase 4"],"answer":"Un aumento della pendenza della depolarizzazione di fase 4","displayAnswer":"Un aumento della pendenza della depolarizzazione di fase 4","explanation":"Una fase 4 più ripida raggiunge prima la soglia e aumenta la frequenza automatica. Spostare la soglia più lontano o rallentare la fase 4 produce l'effetto opposto.","set":"C"},{"id":"q006","source":"1. Vergara -Meccanismi delle aritmie_ automaticità, attività triggerata, rientro - 5 marzo.pdf","page":20,"topic":"Supraventricular tachycardia","type":"mcq","prompt":"Durante una AVNRT tipica, quale percorso segue l'impulso?","options":["Conduzione anterograda sulla via lenta e retrograda sulla via rapida","Attivazione ventricolare senza partecipazione del nodo AV","Conduzione anterograda sulla via rapida e blocco retrogrado completo","Conduzione anterograda sulla via accessoria e retrograda sul fascio di His","Conduzione anterograda e retrograda entrambe sulla via rapida"],"answer":"Conduzione anterograda sulla via lenta e retrograda sulla via rapida","displayAnswer":"Conduzione anterograda sulla via lenta e retrograda sulla via rapida","explanation":"Nella forma slow-fast comune l'impulso scende lungo la via lenta e risale lungo la rapida. Una via accessoria caratterizza invece l'AVRT, non l'AVNRT.","set":"C"},{"id":"q010","source":"10. SPECT e PET nella valutazione di sospetta CAD.pdf","page":5,"topic":"Nuclear cardiology","type":"mcq","prompt":"Una SPECT mostra SSS 12 e SRS 4. Quale interpretazione descrive meglio il SDS risultante?","options":["SDS 16, indicativo solo di cicatrice","SDS 12, che misura esclusivamente la perfusione a riposo","SDS 4, quindi assenza di ischemia","SDS -8, compatibile con artefatto","SDS 8, compatibile con una quota importante di ischemia reversibile"],"answer":"SDS 8, compatibile con una quota importante di ischemia reversibile","displayAnswer":"SDS 8, compatibile con una quota importante di ischemia reversibile","explanation":"Il SDS è SSS meno SRS: 12 - 4 = 8. Una differenza elevata riflette una riduzione inducibile dallo stress, mentre il difetto fisso è rappresentato soprattutto dal punteggio a riposo.","set":"C"},{"id":"q013","source":"10. SPECT e PET nella valutazione di sospetta CAD.pdf","page":11,"topic":"Nuclear cardiology","type":"mcq","prompt":"Perché una perfusione relativa apparentemente normale può sottostimare la malattia in un diabetico con aterosclerosi diffusa?","options":["Il diabete aumenta sempre la riserva coronarica","La perfusione relativa esclude ogni disfunzione microvascolare","La SPECT misura direttamente solo il calcio coronarico","Può essere presente una riduzione globale della riserva coronarica senza difetto regionale evidente","L'assenza di difetti regionali dimostra coronarie normali"],"answer":"Può essere presente una riduzione globale della riserva coronarica senza difetto regionale evidente","displayAnswer":"Può essere presente una riduzione globale della riserva coronarica senza difetto regionale evidente","explanation":"La malattia diffusa o microvascolare può ridurre globalmente la capacità di aumentare il flusso; un confronto solo relativo tra segmenti può quindi apparire normale.","set":"C"},{"id":"q016","source":"11. La Mura Coro-TC e RMN nella CAD.pdf","page":19,"topic":"Cardiac CT and MRI","type":"mcq","prompt":"Osserva le immagini multiparametriche. Quale vantaggio fondamentale offre la CMR in un paziente con sospetta cardiopatia ischemica?","options":["Misura esclusivamente la frequenza cardiaca","Non distingue edema, cicatrice e infiltrazione","Sostituisce sempre la coronarografia terapeutica","Visualizza soltanto il lume coronarico","Integra anatomia, funzione, perfusione e caratterizzazione tissutale nello stesso esame"],"answer":"Integra anatomia, funzione, perfusione e caratterizzazione tissutale nello stesso esame","displayAnswer":"Integra anatomia, funzione, perfusione e caratterizzazione tissutale nello stesso esame","explanation":"La CMR combina cine, perfusione, mapping e late gadolinium enhancement, permettendo di collegare funzione e tessuto. Non è un esame esclusivamente anatomico del lume.","image":"assets/figures/02-p019.jpg","imageAlt":"Figura di riferimento da 11. La Mura Coro-TC e RMN nella CAD.pdf, pagina 19","imagePage":19,"set":"C"},{"id":"q025","source":"12. Cirillo - Accessi vascolari arteriosi e venosi.pdf","page":7,"topic":"Vascular access safety","type":"mcq","prompt":"Perché iniezioni di contrasto troppo ravvicinate nella coronaria destra possono provocare un'aritmia grave?","options":["Trasformano una stenosi in un aneurisma","Accorciano il QT senza effetti ischemici","Bloccano selettivamente l'atrio sinistro","Aumentano sempre il flusso coronarico","Possono prolungare l'ischemia del territorio perfuso e innescare fibrillazione ventricolare"],"answer":"Possono prolungare l'ischemia del territorio perfuso e innescare fibrillazione ventricolare","displayAnswer":"Possono prolungare l'ischemia del territorio perfuso e innescare fibrillazione ventricolare","explanation":"Bisogna consentire lo svuotamento e la riperfusione tra iniezioni: la ripetizione eccessiva può ridurre transitoriamente l'apporto di ossigeno e diventare pro-aritmica.","set":"C"},{"id":"q028","source":"13. Giugliano Accessi vascolari diagnosi e gestione delle complicanze dell'accesso.pdf","page":5,"topic":"Vascular access safety","type":"mcq","prompt":"Dopo PCI femorale un paziente diventa ipoteso, con dolore lombare ma senza grande ematoma inguinale. Quale complicanza va sospettata?","options":["Tamponamento da rottura di parete libera come unica possibilità","Restenosi intrastent immediata","Torsione di punta","Occlusione della via accessoria","Emorragia retroperitoneale"],"answer":"Emorragia retroperitoneale","displayAnswer":"Emorragia retroperitoneale","explanation":"Una puntura femorale troppo alta può causare sanguinamento retroperitoneale occulto. L'assenza di un grande ematoma superficiale non esclude una perdita ematica importante.","set":"C"},{"id":"q031","source":"14. Bardi Coronarografia- identificazione della CAD ostruttiva.pdf","page":1,"topic":"Coronary angiography","type":"mcq","prompt":"Durante la coronarografia, perché è necessario acquisire proiezioni differenti della stessa stenosi?","options":["Per ridurre l'errore da sovrapposizione e foreshortening e ricostruire meglio l'anatomia","Per cambiare la composizione della placca","Per misurare direttamente la riserva microvascolare","Per evitare qualunque uso di contrasto","Per trasformare una lesione cronica in acuta"],"answer":"Per ridurre l'errore da sovrapposizione e foreshortening e ricostruire meglio l'anatomia","displayAnswer":"Per ridurre l'errore da sovrapposizione e foreshortening e ricostruire meglio l'anatomia","explanation":"La coronarografia è una rappresentazione bidimensionale di una struttura tridimensionale; più proiezioni separano i rami e riducono errori geometrici.","set":"C"},{"id":"q035","source":"14. Bardi Coronarografia- identificazione della CAD ostruttiva.pdf","page":14,"topic":"Coronary angiography","type":"mcq","prompt":"Una lesione ostiale dell'IVA viene trattata con stent. Qual è il rischio tecnico principale da evitare nel posizionamento?","options":["Ridurre il calcio coronarico sistemico","Indurre automaticamente microcircolo normale","Lasciare scoperto l'ostio o protrudere in modo inappropriato nel tronco comune","Accorciare il QT","Eliminare il ramo diagonale senza conseguenze"],"answer":"Lasciare scoperto l'ostio o protrudere in modo inappropriato nel tronco comune","displayAnswer":"Lasciare scoperto l'ostio o protrudere in modo inappropriato nel tronco comune","explanation":"Nelle lesioni ostiali servono copertura completa e rispetto dell'anatomia del tronco e della circonflessa; pochi millimetri possono cambiare il risultato.","set":"C"},{"id":"q038","source":"16. Piccolo Rivascolarizzazione nel paziente con disfunzione ventricolare sinistra.pdf","page":19,"topic":"Revascularization and LV dysfunction","type":"mcq","prompt":"Osserva le curve di sopravvivenza a lungo termine. Quale principio emerge dal follow-up esteso dello studio STICH?","options":["La PCI elimina ogni rischio residuo","La chirurgia è sempre superiore già nei primi giorni","Il beneficio prognostico del CABG può diventare evidente solo con un follow-up prolungato","La terapia medica non ha alcun ruolo","La vitalità da sola determina con certezza il beneficio individuale"],"answer":"Il beneficio prognostico del CABG può diventare evidente solo con un follow-up prolungato","displayAnswer":"Il beneficio prognostico del CABG può diventare evidente solo con un follow-up prolungato","explanation":"Nel breve periodo il rischio chirurgico può attenuare il vantaggio; nel follow-up esteso la separazione delle curve sostiene un beneficio tardivo del CABG in pazienti selezionati con cardiomiopatia ischemica.","image":"assets/figures/06-p019.jpg","imageAlt":"Figura di riferimento da 16. Piccolo Rivascolarizzazione nel paziente con disfunzione ventricolare sinistra.pdf, pagina 19","imagePage":19,"set":"C"},{"id":"q044","source":"16. Piccolo Rivascolarizzazione nel paziente con disfunzione ventricolare sinistra.pdf","page":5,"topic":"Revascularization and LV dysfunction","type":"mcq","prompt":"Quale domanda deve precedere la proposta di rivascolarizzazione con obiettivo prognostico in un paziente con bassa FE?","options":["Il paziente preferisce evitare qualunque controllo?","La coronaria più grande è sempre la colpevole?","Esiste miocardio e anatomia suscettibili di beneficio oltre la terapia medica ottimale?","È possibile sospendere tutti i farmaci?","Il QTc è necessariamente corto?"],"answer":"Esiste miocardio e anatomia suscettibili di beneficio oltre la terapia medica ottimale?","displayAnswer":"Esiste miocardio e anatomia suscettibili di beneficio oltre la terapia medica ottimale?","explanation":"Occorre integrare anatomia, sintomi, vitalità/cicatrice, ischemia, comorbilità e prove di efficacia. La presenza di CAD da sola non garantisce un beneficio prognostico dalla procedura.","set":"C"},{"id":"q048","source":"17. Ass. Pilato Rivascolarizzazione miocardica chirurgica.pdf","page":6,"topic":"Surgical revascularization","type":"mcq","prompt":"Una stenosi molto distale dell'IVA non è raggiungibile da un graft peduncolato senza tensione. Quale soluzione può essere considerata?","options":["Impiantare il graft nell'atrio","Ablare il nodo AV","Un graft libero o composito adeguato alla lunghezza necessaria","Usare sempre una vena senza valutarne la qualità","Lasciare il graft in tensione"],"answer":"Un graft libero o composito adeguato alla lunghezza necessaria","displayAnswer":"Un graft libero o composito adeguato alla lunghezza necessaria","explanation":"La configurazione del graft deve garantire lunghezza, flusso e anastomosi senza tensione o torsione. La scelta dipende dall'anatomia e dai condotti disponibili.","set":"C"},{"id":"q053","source":"18. Piccolo Rivascolarizzazione miocardica nelle sindromi coronariche acute.pdf","page":4,"topic":"ACS revascularization","type":"mcq","prompt":"In uno STEMI entro la finestra utile, quale strategia è preferibile quando una rete efficiente consente accesso tempestivo?","options":["CABG elettivo dopo settimane in tutti","Sola aspirina senza riperfusione","Attendere sempre un test da sforzo","PCI primaria","Fibrinolisi seguita da nessuna valutazione"],"answer":"PCI primaria","displayAnswer":"PCI primaria","explanation":"La PCI primaria è la strategia di riperfusione preferita quando eseguibile nei tempi raccomandati. La fibrinolisi resta alternativa quando i ritardi alla PCI sarebbero eccessivi.","set":"C"},{"id":"q056","source":"18. Piccolo Rivascolarizzazione miocardica nelle sindromi coronariche acute.pdf","page":19,"topic":"ACS revascularization","type":"mcq","prompt":"Le placche non culprit ad alto rischio sono osservate sia nello STEMI sia nell'NSTEMI. Quale conseguenza pratica ne deriva?","options":["Lo STEMI non richiede terapia dopo la PCI","La prevenzione secondaria intensiva deve trattare la malattia coronarica come processo diffuso","NSTEMI non è associato ad aterosclerosi","Solo la placca culprit richiede controllo lipidico","Tutte le placche devono essere stentate immediatamente"],"answer":"La prevenzione secondaria intensiva deve trattare la malattia coronarica come processo diffuso","displayAnswer":"La prevenzione secondaria intensiva deve trattare la malattia coronarica come processo diffuso","explanation":"La vulnerabilità non è confinata alla lesione trattata. Statine, controllo dei fattori di rischio e terapia antitrombotica riducono il rischio dell'intero albero coronarico.","set":"C"},{"id":"q059","source":"19. Piccolo Shock cardiogeno - rivascolarizzazione e supporto al circolo.pdf","page":1,"topic":"Cardiogenic shock","type":"mcq","prompt":"Osserva lo spettro dei dispositivi. Quale principio guida la scelta del supporto meccanico nello shock?","options":["Impiantare un dispositivo prima di qualunque valutazione","Scegliere sempre il dispositivo con flusso massimo","Usare IABP ed ECMO come equivalenti","Adeguare portata e tipo di supporto al profilo emodinamico e al ventricolo in insufficienza","Ignorare precarico e postcarico"],"answer":"Adeguare portata e tipo di supporto al profilo emodinamico e al ventricolo in insufficienza","displayAnswer":"Adeguare portata e tipo di supporto al profilo emodinamico e al ventricolo in insufficienza","explanation":"IABP, Impella ed ECMO offrono flussi e effetti diversi su ventricolo, ossigenazione e postcarico. La scelta deve rispondere al fenotipo e a una strategia di uscita.","image":"assets/figures/09-p001.jpg","imageAlt":"Figura di riferimento da 19. Piccolo Shock cardiogeno - rivascolarizzazione e supporto al circolo.pdf, pagina 1","imagePage":1,"set":"C"},{"id":"q064","source":"19. Piccolo Shock cardiogeno - rivascolarizzazione e supporto al circolo.pdf","page":21,"topic":"Cardiogenic shock","type":"mcq","prompt":"Perché un protocollo shock-team può migliorare gli esiti rispetto a decisioni isolate?","options":["Standardizza riconoscimento, rivascolarizzazione, monitoraggio e scelta/escalation del supporto","Evita la valutazione emodinamica","Impedisce la de-escalation dei dispositivi","Ritarda sempre la PCI","Rende inutile il trattamento della causa"],"answer":"Standardizza riconoscimento, rivascolarizzazione, monitoraggio e scelta/escalation del supporto","displayAnswer":"Standardizza riconoscimento, rivascolarizzazione, monitoraggio e scelta/escalation del supporto","explanation":"Lo shock è tempo-dipendente e multidisciplinare. Percorsi condivisi riducono ritardi e variabilità, consentendo anche rivalutazione e rimozione del supporto.","set":"C"},{"id":"q068","source":"2. Strisciuglio - Lo studio elettrofisiologico_ indicazioni, tecnica di esecuzione, parametri registrati - 5 marzo.pdf","page":24,"topic":"Electrophysiology","type":"mcq","prompt":"Durante ablazione RF, che cosa rappresenta l'impedenza misurata tra punta del catetere e tessuto?","options":["La resistenza al passaggio di corrente nel circuito tessuto-cateteri","La saturazione venosa mista","Il periodo refrattario del nodo del seno","La pressione atriale sinistra","La riserva coronarica"],"answer":"La resistenza al passaggio di corrente nel circuito tessuto-cateteri","displayAnswer":"La resistenza al passaggio di corrente nel circuito tessuto-cateteri","explanation":"L'impedenza riflette il circuito elettrico e cambia con contatto, riscaldamento e formazione della lesione; un aumento brusco può segnalare surriscaldamento.","set":"C"},{"id":"q072","source":"2. Strisciuglio - Lo studio elettrofisiologico_ indicazioni, tecnica di esecuzione, parametri registrati - 5 marzo.pdf","page":25,"topic":"Electrophysiology","type":"mcq","prompt":"Dopo una lesione RF non si osserva l'effetto atteso. Qual è il primo controllo tecnico ragionevole?","options":["Aumentare automaticamente la potenza al massimo","Impiantare subito un ICD","Somministrare contrasto nella coronaria destra","Verificare stabilità, contatto, posizione e parametri di erogazione","Concludere che il meccanismo non è aritmico"],"answer":"Verificare stabilità, contatto, posizione e parametri di erogazione","displayAnswer":"Verificare stabilità, contatto, posizione e parametri di erogazione","explanation":"Un fallimento può dipendere da localizzazione o qualità della lesione. Prima di aumentare energia bisogna rivalutare segnale, anatomia e sicurezza.","set":"C"},{"id":"q076","source":"20. Di Serafino Fisiologia coronarica nel paziente candidato a rivascolarizzazione coronarica; ANOCA e INOCA.pdf","page":7,"topic":"Coronary physiology and INOCA","type":"mcq","prompt":"Che cosa indica un PPG index elevato durante pullback pressorio?","options":["Necrosi transmurale","Malattia esclusivamente microvascolare","Una distribuzione completamente diffusa","Un pattern più focale con caduta di pressione concentrata","Assenza di gradiente"],"answer":"Un pattern più focale con caduta di pressione concentrata","displayAnswer":"Un pattern più focale con caduta di pressione concentrata","explanation":"Il PPG quantifica la distribuzione longitudinale della perdita pressoria: valori alti orientano verso lesioni focali potenzialmente più correggibili con PCI.","set":"C"},{"id":"q080","source":"20. Di Serafino Fisiologia coronarica nel paziente candidato a rivascolarizzazione coronarica; ANOCA e INOCA.pdf","page":10,"topic":"Coronary physiology and INOCA","type":"mcq","prompt":"Perché lo stesso valore FFR post-PCI può essere interpretato considerando il vaso trattato?","options":["La pressione aortica non entra nel calcolo","L'IVA non perfunde miocardio","Il valore è indipendente da anatomia e diffusione","FFR cambia con il gruppo sanguigno","Lunghezza del vaso e quantità di miocardio perfuso influenzano il gradiente residuo"],"answer":"Lunghezza del vaso e quantità di miocardio perfuso influenzano il gradiente residuo","displayAnswer":"Lunghezza del vaso e quantità di miocardio perfuso influenzano il gradiente residuo","explanation":"Vasi lunghi come l'IVA possono mostrare perdite pressorie diffuse maggiori. Il numero va integrato con pullback, anatomia e qualità del risultato.","set":"C"},{"id":"q084","source":"23. Di Seraf.  MINOCA (by giovanni vitale.pdf","page":2,"topic":"MINOCA","type":"mcq","prompt":"Quale scenario suggerisce un MINOCA non aterosclerotico da embolia coronarica?","options":["BBS isolato senza troponina","Stenosi focale con FFR negativo","Placca calcifica stabile senza trombo","Infarto con coronarie non ostruttive in un paziente con fibrillazione atriale o fonte emboligena","Bradicardia sinusale notturna"],"answer":"Infarto con coronarie non ostruttive in un paziente con fibrillazione atriale o fonte emboligena","displayAnswer":"Infarto con coronarie non ostruttive in un paziente con fibrillazione atriale o fonte emboligena","explanation":"Tromboembolia può occludere transitoriamente il compartimento epicardico o microvascolare. La ricerca di fonti emboligene modifica la prevenzione secondaria.","set":"C"},{"id":"q087","source":"23. Di Seraf.  MINOCA (by giovanni vitale.pdf","page":6,"topic":"MINOCA","type":"mcq","prompt":"Un test all'acetilcolina riproduce dolore e alterazioni ischemiche con vasocostrizione epicardica marcata. Qual è il meccanismo?","options":["Cicatrice transmurale fissa","Disfunzione del nodo del seno","Rientro nodale","Embolia polmonare","Spasmo coronarico epicardico"],"answer":"Spasmo coronarico epicardico","displayAnswer":"Spasmo coronarico epicardico","explanation":"La provocazione documenta un endotipo vasospastico, che orienta verso calcio-antagonisti e nitrati anziché una terapia generica del MINOCA.","set":"C"},{"id":"q091","source":"25-26 Franzone - Terapia medica ottimale nelle sindromi coronariche acute e croniche.pdf","page":1,"topic":"Antiplatelet and medical therapy","type":"mcq","prompt":"Osserva i criteri ARC-HBR. Quale paziente soddisfa la definizione di alto rischio emorragico?","options":["Un paziente con almeno un criterio maggiore oppure almeno due criteri minori","Qualunque paziente con uno stent","Solo chi assume statine","Solo chi ha avuto tre infarti","Un paziente senza alcun criterio ma con età giovane"],"answer":"Un paziente con almeno un criterio maggiore oppure almeno due criteri minori","displayAnswer":"Un paziente con almeno un criterio maggiore oppure almeno due criteri minori","explanation":"ARC-HBR standardizza un rischio di sanguinamento maggiore a un anno. La classificazione dipende da criteri maggiori/minori, non dalla sola presenza di PCI.","image":"assets/figures/14-p001.jpg","imageAlt":"Figura di riferimento da 25-26 Franzone - Terapia medica ottimale nelle sindromi coronariche acute e croniche.pdf, pagina 1","imagePage":1,"set":"C"},{"id":"q096","source":"25-26 Franzone - Terapia medica ottimale nelle sindromi coronariche acute e croniche.pdf","page":15,"topic":"Antiplatelet and medical therapy","type":"mcq","prompt":"Passando da ticagrelor o prasugrel a clopidogrel nella fase precoce, perché può servire una dose di carico?","options":["Per bloccare il fattore Xa","Perché clopidogrel agisce immediatamente senza metabolismo","Per aumentare il rischio emorragico intenzionalmente","Per evitare una finestra di insufficiente inibizione piastrinica durante il cambio","Per neutralizzare l'aspirina"],"answer":"Per evitare una finestra di insufficiente inibizione piastrinica durante il cambio","displayAnswer":"Per evitare una finestra di insufficiente inibizione piastrinica durante il cambio","explanation":"Il clopidogrel ha onset più lento e risposta variabile. Timing e dose di carico dipendono dal contesto, dal sanguinamento e dal farmaco precedente.","set":"C"},{"id":"q100","source":"28. Cirillo Terapia antitrombotica nelle sindromi coronariche acute - dal pretrattamento alla dimissione.pdf","page":6,"topic":"Antithrombotic therapy","type":"mcq","prompt":"Perché clopidogrel è meno prevedibile di prasugrel o ticagrelor nella fase acuta?","options":["È un inibitore diretto della trombina","Ha sempre effetto completo in pochi minuti","È somministrabile solo per via endovenosa","Ha onset più lento e dipende maggiormente dall'attivazione metabolica","Non agisce sulle piastrine"],"answer":"Ha onset più lento e dipende maggiormente dall'attivazione metabolica","displayAnswer":"Ha onset più lento e dipende maggiormente dall'attivazione metabolica","explanation":"Clopidogrel è un profarmaco con variabilità genetica e clinica; i farmaci più potenti raggiungono in genere un'inibizione più rapida e consistente.","set":"C"},{"id":"q103","source":"28. Cirillo Terapia antitrombotica nelle sindromi coronariche acute - dal pretrattamento alla dimissione.pdf","page":16,"topic":"Antithrombotic therapy","type":"mcq","prompt":"Perché l'aspirina aumenta il rischio di sanguinamento gastrointestinale?","options":["Causa vasospasmo coronarico","Aumenta la produzione di muco","Blocca selettivamente il fattore Xa","Stimola il recettore P2Y12","Riduce prostaglandine protettive della mucosa attraverso l'inibizione della ciclossigenasi"],"answer":"Riduce prostaglandine protettive della mucosa attraverso l'inibizione della ciclossigenasi","displayAnswer":"Riduce prostaglandine protettive della mucosa attraverso l'inibizione della ciclossigenasi","explanation":"Lo stesso meccanismo COX che riduce trombossano limita la protezione mucosale. Nei pazienti a rischio si considerano gastroprotezione e strategie antitrombotiche appropriate.","set":"C"},{"id":"q108","source":"3. Rapacciuolo - Disfunzione del nodo del seno e del nodo AV- fisiopatologia, test diagnostici, trattamento.pdf","page":2,"topic":"Bradyarrhythmias","type":"mcq","prompt":"Un paziente con disfunzione sinusale riferisce astenia e presincope durante pause documentate. Qual è il trattamento definitivo più probabile?","options":["Fibrinolisi","Pacing permanente dopo esclusione di cause reversibili","ECMO","DAPT prolungata","Ablazione della via lenta"],"answer":"Pacing permanente dopo esclusione di cause reversibili","displayAnswer":"Pacing permanente dopo esclusione di cause reversibili","explanation":"La disfunzione sinusale sintomatica con correlazione documentata è una classica indicazione al pacing. Farmaci e condizioni correggibili vanno valutati prima.","set":"C"},{"id":"q111","source":"3. Rapacciuolo - Disfunzione del nodo del seno e del nodo AV- fisiopatologia, test diagnostici, trattamento.pdf","page":7,"topic":"Bradyarrhythmias","type":"mcq","prompt":"Sincope rara, blocco di branca e SEF non diagnostico: quale strumento è utile per correlare un futuro episodio al ritmo?","options":["Coro-TC annuale","Holter di cinque minuti","Loop recorder impiantabile","SPECT a riposo","Misurazione singola della troponina"],"answer":"Loop recorder impiantabile","displayAnswer":"Loop recorder impiantabile","explanation":"L'ILR offre monitoraggio prolungato quando gli episodi sono sporadici e la diagnosi resta incerta.","set":"C"},{"id":"q116","source":"31. Spaccarotella Dissezioni Coronariche Spontanee (1).pdf","page":1,"topic":"SCAD","type":"mcq","prompt":"Quale profilo clinico dovrebbe aumentare il sospetto di SCAD?","options":["Donna relativamente giovane con SCA e pochi fattori aterosclerotici tradizionali","Paziente con solo BAV notturno","Paziente con WPW asintomatico","Soggetto con pericardite virale","Anziano con calcificazioni diffuse e stenosi focali multiple"],"answer":"Donna relativamente giovane con SCA e pochi fattori aterosclerotici tradizionali","displayAnswer":"Donna relativamente giovane con SCA e pochi fattori aterosclerotici tradizionali","explanation":"SCAD è una causa importante di SCA soprattutto in donne giovani o di mezza età e può associarsi a displasia fibromuscolare e trigger emotivi/fisici.","set":"C"},{"id":"q119","source":"31. Spaccarotella Dissezioni Coronariche Spontanee (1).pdf","page":4,"topic":"SCAD","type":"mcq","prompt":"Una dissezione del tronco comune viene rivalutata dopo stabilizzazione e non vi è ischemia. Perché può essere scelta un'osservazione stretta?","options":["Il tronco comune non perfunde miocardio","La guarigione spontanea è possibile e l'intervento ha rischi tecnici importanti","Il CABG è vietato in assoluto","La troponina esclude ischemia","La SCAD non può mai peggiorare"],"answer":"La guarigione spontanea è possibile e l'intervento ha rischi tecnici importanti","displayAnswer":"La guarigione spontanea è possibile e l'intervento ha rischi tecnici importanti","explanation":"La sede è ad alto rischio e richiede monitoraggio esperto; la decisione dipende da flusso, sintomi, instabilità e fattibilità di PCI/CABG.","set":"C"},{"id":"q123","source":"32. Losi - complicanze meccaniche dell' infarto.pdf","page":2,"topic":"Mechanical complications of MI","type":"mcq","prompt":"Osserva ECG e schema anatomico. Un infarto inferiore con ipotensione, turgore giugulare e polmoni liberi suggerisce soprattutto:","options":["Infarto del ventricolo destro","AVNRT","Disfunzione microvascolare isolata","Rottura del setto con edema polmonare isolato","Tamponamento cronico asintomatico"],"answer":"Infarto del ventricolo destro","displayAnswer":"Infarto del ventricolo destro","explanation":"Il coinvolgimento del ventricolo destro riduce il riempimento sinistro: ipotensione e congestione venosa con polmoni relativamente liberi sono indizi classici.","image":"assets/figures/18-p002.jpg","imageAlt":"Figura di riferimento da 32. Losi - complicanze meccaniche dell' infarto.pdf, pagina 2","imagePage":2,"set":"C"},{"id":"q128","source":"32. Losi - complicanze meccaniche dell' infarto.pdf","page":7,"topic":"Mechanical complications of MI","type":"mcq","prompt":"Perché ripetere l'ecocardiogramma è essenziale se il quadro clinico cambia nelle prime ore dopo IMA?","options":["L'eco iniziale è sempre errato","Le complicanze meccaniche possono comparire dinamicamente dopo un esame iniziale quasi normale","La troponina rende inutile l'imaging","Le rotture avvengono solo prima del dolore","La funzione ventricolare non cambia"],"answer":"Le complicanze meccaniche possono comparire dinamicamente dopo un esame iniziale quasi normale","displayAnswer":"Le complicanze meccaniche possono comparire dinamicamente dopo un esame iniziale quasi normale","explanation":"Un primo esame non esclude eventi successivi. Nuova ipotensione, soffio, congestione o dolore richiedono rivalutazione immediata.","set":"C"},{"id":"q132","source":"4. Pergola - Short QT, Long QT, TV idiopatica.pdf","page":6,"topic":"Inherited repolarization disorders","type":"mcq","prompt":"Le cellule M hanno una minore corrente IKs. Quale conseguenza favorisce la LQTS?","options":["Aumento automatico della conduzione AV","Potenziale d'azione più lungo e maggiore dispersione transmurale","Scomparsa della fase 3","Ripolarizzazione più rapida e uniforme","Accorciamento del QT"],"answer":"Potenziale d'azione più lungo e maggiore dispersione transmurale","displayAnswer":"Potenziale d'azione più lungo e maggiore dispersione transmurale","explanation":"Una ridotta corrente ripolarizzante prolunga il potenziale d'azione, soprattutto in condizioni di stress specifiche, accentuando l'eterogeneità.","set":"C"},{"id":"q136","source":"4. Pergola - Short QT, Long QT, TV idiopatica.pdf","page":36,"topic":"Inherited repolarization disorders","type":"mcq","prompt":"Un farmaco che accorcia il QT in una SQTS induce però maggiore dispersione e fibrillazione ventricolare. Qual è la lezione?","options":["La terapia va scelta solo dal colore dell'ECG","Normalizzare il QT numerico non garantisce una ripolarizzazione sicura e omogenea","Qualunque accorciamento è protettivo","La fibrillazione non dipende dalla ripolarizzazione","Il QT non ha relazione con refrattarietà"],"answer":"Normalizzare il QT numerico non garantisce una ripolarizzazione sicura e omogenea","displayAnswer":"Normalizzare il QT numerico non garantisce una ripolarizzazione sicura e omogenea","explanation":"Il target è ridurre l'aritmogenicità, non solo modificare un intervallo. Effetti su dispersione, refrattarietà e conduzione sono essenziali.","set":"C"},{"id":"q140","source":"5. Rapacciuolo prevenzione SCD + dispositivi per HF 2.pdf","page":3,"topic":"Sudden cardiac death and devices","type":"mcq","prompt":"Qual è il ruolo di un ICD nella prevenzione secondaria?","options":["Sostituire ogni ablazione","Interrompere rapidamente future TV/FV in sopravvissuti selezionati senza causa reversibile","Curare lo scompenso con aumento della FE in tutti","Prevenire la formazione di aterosclerosi","Diagnosticare stenosi coronariche"],"answer":"Interrompere rapidamente future TV/FV in sopravvissuti selezionati senza causa reversibile","displayAnswer":"Interrompere rapidamente future TV/FV in sopravvissuti selezionati senza causa reversibile","explanation":"L'ICD tratta l'aritmia quando compare; non rimuove il substrato e non sostituisce terapia della causa, farmaci o ablazione.","set":"C"},{"id":"q143","source":"5. Rapacciuolo prevenzione SCD + dispositivi per HF 2.pdf","page":10,"topic":"Sudden cardiac death and devices","type":"mcq","prompt":"Sincope in un portatore di ICD significa necessariamente aritmia ventricolare?","options":["No, perché l'ICD impedisce ogni sincope","No: vanno considerate aritmie atriali, cause neuromediate, ipotensione e malfunzionamento","Sì, sempre FV","Sì, sempre trombosi di stent","No, perché i device non registrano eventi"],"answer":"No: vanno considerate aritmie atriali, cause neuromediate, ipotensione e malfunzionamento","displayAnswer":"No: vanno considerate aritmie atriali, cause neuromediate, ipotensione e malfunzionamento","explanation":"L'interrogazione del dispositivo collega sintomi e ritmo, ma la diagnosi differenziale resta ampia.","set":"C"},{"id":"q148","source":"5. Vergara -CRT e ICD Trial Clinici-.pdf","page":14,"topic":"Cardiac resynchronization therapy","type":"mcq","prompt":"Perché una cicatrice posterolaterale estesa può ridurre la risposta alla CRT?","options":["Trasforma LBBB in WPW","Aumenta automaticamente la FE","Impedisce ogni sensing atriale","Il lead può stimolare tessuto non vitale con scarsa cattura meccanica","La cicatrice accelera sempre la conduzione"],"answer":"Il lead può stimolare tessuto non vitale con scarsa cattura meccanica","displayAnswer":"Il lead può stimolare tessuto non vitale con scarsa cattura meccanica","explanation":"La sede del lead deve evitare cicatrice e raggiungere un segmento tardivo ma vitale. Imaging e anatomia venosa possono guidare l'impianto.","set":"C"},{"id":"q151","source":"6 Strisciugno Sincope.pdf","page":1,"topic":"Syncope","type":"mcq","prompt":"Quale caratteristica favorisce sincope rispetto a crisi epilettica?","options":["Morsicatura laterale della lingua","Movimenti tonico-clonici prolungati prima della caduta","Confusione post-critica prolungata","Cianosi persistente","Recupero rapido e completo con prodromi vasovagali"],"answer":"Recupero rapido e completo con prodromi vasovagali","displayAnswer":"Recupero rapido e completo con prodromi vasovagali","explanation":"Brevi movimenti possono comparire anche nella sincope; contesto, prodromi, durata e fase post-evento sono più discriminanti del singolo segno.","set":"C"},{"id":"q154","source":"6 Strisciugno Sincope.pdf","page":6,"topic":"Syncope","type":"mcq","prompt":"Un paziente con Brugada e sincope inspiegata ha ILR non diagnostico dopo anni. Perché può essere ragionevole continuare il monitoraggio?","options":["L'ILR tratta la FV","Gli eventi sono rari ma potenzialmente aritmici e la correlazione sintomo-ritmo resta decisiva","La sincope non può recidivare","Il Brugada esclude aritmie","Il monitoraggio breve è sempre sufficiente"],"answer":"Gli eventi sono rari ma potenzialmente aritmici e la correlazione sintomo-ritmo resta decisiva","displayAnswer":"Gli eventi sono rari ma potenzialmente aritmici e la correlazione sintomo-ritmo resta decisiva","explanation":"In eventi infrequenti, una finestra lunga aumenta la resa diagnostica. La decisione deve comunque considerare il rischio complessivo e l'indicazione a ICD.","set":"C"},{"id":"q158","source":"6. Strisciuglio Wolff Parkinson White.pdf","page":9,"topic":"WPW and accessory pathways","type":"mcq","prompt":"Osserva l'ECG. Quale combinazione a ritmo sinusale sostiene una preeccitazione ventricolare?","options":["Blocco AV completo","Onde Q isolate senza alterazioni di conduzione","ST sopraslivellato diffuso con PR depresso","PR corto, onda delta e QRS inizialmente slargato","PR lungo e QRS stretto senza delta"],"answer":"PR corto, onda delta e QRS inizialmente slargato","displayAnswer":"PR corto, onda delta e QRS inizialmente slargato","explanation":"La via accessoria anticipa parte dell'attivazione ventricolare, generando onda delta e accorciamento del PR. L'espressione può variare con la conduzione nodale.","image":"assets/figures/23-p009.jpg","imageAlt":"Figura di riferimento da 6. Strisciuglio Wolff Parkinson White.pdf, pagina 9","imagePage":9,"set":"C"},{"id":"q164","source":"6. Strisciuglio Wolff Parkinson White.pdf","page":13,"topic":"WPW and accessory pathways","type":"mcq","prompt":"Durante AVRT ortodromica, quale strategia di mappaggio localizza la via accessoria?","options":["Misurare il calcio coronarico","Mappare solo il nodo del seno","Campionare la CFR nella LAD","Cercare il QT più lungo","Cercare il punto di attivazione atriale retrograda più precoce lungo l'anello"],"answer":"Cercare il punto di attivazione atriale retrograda più precoce lungo l'anello","displayAnswer":"Cercare il punto di attivazione atriale retrograda più precoce lungo l'anello","explanation":"La via conduce dal ventricolo all'atrio durante AVRT ortodromica; il segnale atriale più precoce identifica il sito d'inserzione.","set":"C"},{"id":"q168","source":"7. Vergara Tachicardia da rientro nodale 2.pdf","page":6,"topic":"AVNRT","type":"mcq","prompt":"Che cosa rappresentano via lenta e via rapida nell'AVNRT moderna?","options":["Ingressi e tessuti nodali/perinodali con proprietà di conduzione e refrattarietà differenti","Due aree di cicatrice ventricolare","Due coronarie","Due vie accessorie ventricolo-atriali obbligatorie","Due fasci di Purkinje indipendenti"],"answer":"Ingressi e tessuti nodali/perinodali con proprietà di conduzione e refrattarietà differenti","displayAnswer":"Ingressi e tessuti nodali/perinodali con proprietà di conduzione e refrattarietà differenti","explanation":"Non sono semplicemente due cavi anatomici isolati; il circuito coinvolge tessuto nodale e transizioni perinodali.","set":"C"},{"id":"q171","source":"7. Vergara Tachicardia da rientro nodale 2.pdf","page":22,"topic":"AVNRT","type":"mcq","prompt":"Una tachicardia incessante con conduzione retrograda lenta e decrementale attraverso una via accessoria suggerisce:","options":["AVNRT tipica","Blocco AV completo","PJRT","Flutter ventricolare","Torsione di punta"],"answer":"PJRT","displayAnswer":"PJRT","explanation":"La permanent junctional reciprocating tachycardia è una AVRT ortodromica mediata da via accessoria retrograda lenta, spesso con RP lungo.","set":"C"},{"id":"q175","source":"8. Vergara Sindromi Genetiche Vergara (Brugada, ER, CPVT) 2.pdf","page":4,"topic":"Inherited arrhythmia syndromes","type":"mcq","prompt":"Un pattern tipo 1 compare solo dopo ajmalina in un paziente asintomatico. Qual è la conclusione più prudente?","options":["FV certa entro un anno","ICD obbligatorio","Il reperto aumenta la probabilità diagnostica ma rischio e diagnosi richiedono contesto completo","Brugada esclusa","Nessun follow-up necessario"],"answer":"Il reperto aumenta la probabilità diagnostica ma rischio e diagnosi richiedono contesto completo","displayAnswer":"Il reperto aumenta la probabilità diagnostica ma rischio e diagnosi richiedono contesto completo","explanation":"Un test provocativo positivo non equivale automaticamente ad alto rischio. Sintomi, pattern spontaneo, familiarità e altri elementi guidano la gestione.","set":"C"},{"id":"q179","source":"8. Vergara Sindromi Genetiche Vergara (Brugada, ER, CPVT) 2.pdf","page":36,"topic":"Inherited arrhythmia syndromes","type":"mcq","prompt":"Un adolescente ha sincope durante esercizio, cuore strutturalmente normale e TV bidirezionale. Qual è la diagnosi più probabile?","options":["STEMI","Blocco AV completo","CPVT","AVNRT","Sincope vasovagale semplice"],"answer":"CPVT","displayAnswer":"CPVT","explanation":"La CPVT è scatenata da catecolamine e spesso mostra ectopia ventricolare polimorfa/bidirezionale durante sforzo. Il beta-blocco è centrale.","set":"C"},{"id":"q183","source":"9. Ciampi Ecostress.pdf","page":3,"topic":"Stress echocardiography","type":"mcq","prompt":"Qual è il meccanismo con cui dipiridamolo o adenosina valutano la riserva coronarica?","options":["Riducono il flusso in tutti i vasi allo stesso modo","Inducono iperemia e mettono in evidenza la capacità di aumentare il flusso","Bloccano irreversibilmente P2Y12","Aumentano la cicatrice","Creano una stenosi anatomica"],"answer":"Inducono iperemia e mettono in evidenza la capacità di aumentare il flusso","displayAnswer":"Inducono iperemia e mettono in evidenza la capacità di aumentare il flusso","explanation":"Il rapporto tra velocità iperemica e basale stima la CFVR. Una risposta attenuata può riflettere malattia epicardica o microvascolare.","set":"C"},{"id":"q186","source":"9. Ciampi Ecostress.pdf","page":17,"topic":"Stress echocardiography","type":"mcq","prompt":"Durante ecostress compare sopraslivellamento ST, nuove anomalie di cinetica e riduzione della riserva. Qual è la lettura più appropriata?","options":["Test negativo","Profilo ad alto rischio che richiede valutazione coronarica tempestiva","Diagnosi certa di sincope riflessa","Risposta fisiologica","Solo ansia"],"answer":"Profilo ad alto rischio che richiede valutazione coronarica tempestiva","displayAnswer":"Profilo ad alto rischio che richiede valutazione coronarica tempestiva","explanation":"L'integrazione di ECG, cinetica e flusso aumenta specificità e stratificazione. Il sopraslivellamento è un segnale più grave del semplice sottoslivellamento.","set":"C"},{"id":"q190","source":"Lezione Gargiulo 2026.pdf","page":2,"topic":"ACS risk and antithrombotic strategy","type":"mcq","prompt":"Perché la DAPT ha superato strategie più semplici dopo stent?","options":["Agisce su vie piastriniche complementari e riduce trombosi di stent ed eventi","Elimina il rischio emorragico","Scioglie direttamente la placca","Sostituisce ogni anticoagulante in qualunque indicazione","Tratta la disfunzione ventricolare"],"answer":"Agisce su vie piastriniche complementari e riduce trombosi di stent ed eventi","displayAnswer":"Agisce su vie piastriniche complementari e riduce trombosi di stent ed eventi","explanation":"Aspirina e inibizione P2Y12 riducono l'attivazione piastrinica con meccanismi distinti; il vantaggio richiede però gestione del sanguinamento.","set":"C"},{"id":"q193","source":"Lezione Gargiulo 2026.pdf","page":11,"topic":"ACS risk and antithrombotic strategy","type":"mcq","prompt":"Quale paziente è ARC-HBR?","options":["Chi non ha mai sanguinato","Solo chi ha LDL elevato","Solo chi ha tre stent","Chi presenta almeno un criterio maggiore o due criteri minori","Chiunque abbia una SCA"],"answer":"Chi presenta almeno un criterio maggiore o due criteri minori","displayAnswer":"Chi presenta almeno un criterio maggiore o due criteri minori","explanation":"La definizione mira a un rischio di sanguinamento maggiore ≥4% o intracranico ≥1% a un anno e standardizza la selezione.","set":"C"},{"id":"q197","source":"guidelines 2023-SCA.pdf","page":28,"topic":"ACS guidelines","type":"mcq","prompt":"Un paziente con NSTE-ACS ha diagnosi confermata e criteri di alto rischio. Quale strategia è appropriata?","options":["Attendere settimane per test da sforzo","Considerare angiografia invasiva precoce, generalmente entro 24 ore","Nessuna terapia antitrombotica","Fibrinolisi sistematica","Dimissione senza monitoraggio"],"answer":"Considerare angiografia invasiva precoce, generalmente entro 24 ore","displayAnswer":"Considerare angiografia invasiva precoce, generalmente entro 24 ore","explanation":"L'alto rischio nel NSTE-ACS orienta a una strategia invasiva precoce; instabilità emodinamica o ischemia refrattaria richiedono approccio immediato.","set":"C"}],"D":[{"id":"q004","source":"1. Vergara -Meccanismi delle aritmie_ automaticità, attività triggerata, rientro - 5 marzo.pdf","page":17,"topic":"Arrhythmia mechanisms","type":"mcq","prompt":"Un'aritmia compare durante catecolamine o pacing e non nasce spontaneamente a riposo. Quale meccanismo è più probabile?","options":["Soppressione da overdrive","Automaticità normale del nodo del seno","Blocco AV completo","Rientro anatomico obbligato","Attività triggerata da post-potenziali"],"answer":"Attività triggerata da post-potenziali","displayAnswer":"Attività triggerata da post-potenziali","explanation":"L'attività triggerata necessita di un potenziale d'azione precedente e di un trigger, spesso catecolamine, pacing o sovraccarico di calcio. L'automatismo, invece, può generare impulsi spontaneamente.","set":"D"},{"id":"q007","source":"1. Vergara -Meccanismi delle aritmie_ automaticità, attività triggerata, rientro - 5 marzo.pdf","page":24,"topic":"Supraventricular tachycardia","type":"mcq","prompt":"Una tachicardia regolare a QRS stretto presenta onde P retrograde nel tratto ST e RP >70 ms in un paziente con preeccitazione intermittente. Qual è il meccanismo più coerente?","options":["Tachicardia ventricolare monomorfa","Blocco AV di secondo grado","Fibrillazione atriale preeccitata","AVRT antidromica","AVRT ortodromica con conduzione anterograda attraverso il nodo AV"],"answer":"AVRT ortodromica con conduzione anterograda attraverso il nodo AV","displayAnswer":"AVRT ortodromica con conduzione anterograda attraverso il nodo AV","explanation":"Nell'AVRT ortodromica il ventricolo è attivato attraverso il sistema His-Purkinje, quindi il QRS è in genere stretto; la via accessoria completa il circuito in senso retrogrado. L'antidromica produce QRS largo.","set":"D"},{"id":"q011","source":"10. SPECT e PET nella valutazione di sospetta CAD.pdf","page":4,"topic":"Nuclear cardiology","type":"mcq","prompt":"Un paziente con blocco di branca sinistra non può svolgere esercizio adeguato. Quale stress è preferibile per una scintigrafia di perfusione?","options":["Pacing ventricolare rapido","Solo esercizio massimale","Nessuno stress, solo acquisizione a riposo","Test con atropina isolata","Stress farmacologico vasodilatatore"],"answer":"Stress farmacologico vasodilatatore","displayAnswer":"Stress farmacologico vasodilatatore","explanation":"Nel blocco di branca sinistra si preferisce uno stress vasodilatatore per ridurre interpretazioni fuorvianti legate all'esercizio e alla cinetica settale.","set":"D"},{"id":"q014","source":"10. SPECT e PET nella valutazione di sospetta CAD.pdf","page":13,"topic":"Nuclear cardiology","type":"mcq","prompt":"Un paziente ha PET senza difetto focale, ma riserva coronarica globalmente ridotta. Qual è il significato clinico più corretto?","options":["Non modifica la stratificazione del rischio","Indica sempre una stenosi focale della LAD","La riserva ridotta mantiene valore prognostico anche senza difetto regionale","Esclude aterosclerosi diffusa","Il risultato è necessariamente un falso positivo"],"answer":"La riserva ridotta mantiene valore prognostico anche senza difetto regionale","displayAnswer":"La riserva ridotta mantiene valore prognostico anche senza difetto regionale","explanation":"La riserva coronarica integra funzione epicardica e microvascolare ed è uno stratificatore prognostico indipendente dalla presenza di un difetto focale.","set":"D"},{"id":"q018","source":"11. La Mura Coro-TC e RMN nella CAD.pdf","page":7,"topic":"Cardiac CT and MRI","type":"mcq","prompt":"Alla coro-TC, quale reperto definisce più correttamente una restenosi intrastent?","options":["Riduzione del lume intrastent superiore al 50%","Aumento del calibro del vaso oltre il 50%","Qualsiasi iperplasia neointimale inferiore al 20%","Presenza del solo marker radiopaco","Assenza totale di calcio nello stent"],"answer":"Riduzione del lume intrastent superiore al 50%","displayAnswer":"Riduzione del lume intrastent superiore al 50%","explanation":"La lezione distingue iperplasia neointimale con stenosi <50%, restenosi >50% e occlusione al 100%.","set":"D"},{"id":"q021","source":"11. La Mura Coro-TC e RMN nella CAD.pdf","page":4,"topic":"Cardiac CT and MRI","type":"mcq","prompt":"Una CMR da stress evidenzia ipoperfusione inducibile senza alterazioni cine a riposo. Quale conclusione è più appropriata?","options":["La perfusione da stress misura solo la vitalità","L'assenza di acinesia a riposo esclude CAD","La coronarografia non potrà mai mostrare lesioni","La funzione basale normale non esclude ischemia inducibile","Il reperto dimostra necessariamente miocardite"],"answer":"La funzione basale normale non esclude ischemia inducibile","displayAnswer":"La funzione basale normale non esclude ischemia inducibile","explanation":"Le sequenze cine possono essere normali a riposo mentre la perfusione da stress rivela una riserva inadeguata. Le informazioni sono complementari.","set":"D"},{"id":"q023","source":"12. Cirillo - Accessi vascolari arteriosi e venosi.pdf","page":1,"topic":"Vascular access safety","type":"mcq","prompt":"Osserva le complicanze illustrate. Qual è il messaggio operativo principale per ridurre danni locali dopo accesso arterioso?","options":["Le complicanze locali sono sempre solo estetiche","La compressione non è necessaria dopo rimozione della guaina","L'accesso femorale elimina il rischio di sanguinamento","Tecnica di puntura, scelta del sito e controllo dell'emostasi devono essere accurati","La dimensione dell'ematoma non dipende mai dalla tecnica"],"answer":"Tecnica di puntura, scelta del sito e controllo dell'emostasi devono essere accurati","displayAnswer":"Tecnica di puntura, scelta del sito e controllo dell'emostasi devono essere accurati","explanation":"Ematomi estesi e lesioni locali possono derivare da puntura o compressione inadeguate. La prevenzione comincia da tecnica, sede e sorveglianza, non dal solo trattamento tardivo.","image":"assets/figures/03-p001.jpg","imageAlt":"Figura di riferimento da 12. Cirillo - Accessi vascolari arteriosi e venosi.pdf, pagina 1","imagePage":1,"set":"D"},{"id":"q030","source":"13. Giugliano Accessi vascolari diagnosi e gestione delle complicanze dell'accesso.pdf","page":5,"topic":"Vascular access safety","type":"mcq","prompt":"Quale osservazione rende l'accesso femorale un determinante prognostico e non soltanto un problema locale?","options":["Il femorale causa sempre ictus","Ogni ematoma femorale richiede chirurgia","L'accesso radiale non può essere usato nella PCI","Il rischio emorragico è indipendente dalla mortalità","Il sanguinamento maggiore aumenta trasfusioni, degenza e mortalità precoce"],"answer":"Il sanguinamento maggiore aumenta trasfusioni, degenza e mortalità precoce","displayAnswer":"Il sanguinamento maggiore aumenta trasfusioni, degenza e mortalità precoce","explanation":"Le complicanze emorragiche maggiori hanno conseguenze sistemiche e si associano a esiti peggiori; per questo la strategia di accesso fa parte della gestione del rischio.","set":"D"},{"id":"q034","source":"14. Bardi Coronarografia- identificazione della CAD ostruttiva.pdf","page":8,"topic":"Coronary angiography","type":"mcq","prompt":"In una lesione di biforcazione, quale informazione è clinicamente più utile rispetto alla sola etichetta di Duke?","options":["Il rapporto tra placca, carena e coinvolgimento dei due rami","La sola età del paziente","Il valore di QTc","La presenza di bradicardia notturna","Il gruppo sanguigno"],"answer":"Il rapporto tra placca, carena e coinvolgimento dei due rami","displayAnswer":"Il rapporto tra placca, carena e coinvolgimento dei due rami","explanation":"Le classificazioni moderne delle biforcazioni descrivono il coinvolgimento di ramo principale e laterale, informazione che guida strategia e protezione dei rami.","set":"D"},{"id":"q039","source":"16. Piccolo Rivascolarizzazione nel paziente con disfunzione ventricolare sinistra.pdf","page":3,"topic":"Revascularization and LV dysfunction","type":"mcq","prompt":"Perché la combinazione di scompenso cardiaco e CAD identifica una popolazione a rischio particolarmente elevato?","options":["Lo scompenso annulla il rischio aterotrombotico","La presenza di CAD rende sempre reversibile la disfunzione","La CAD protegge dalle aritmie ventricolari","La coronaropatia aggiunge ischemia, infarto e rimodellamento alla disfunzione ventricolare","La funzione ventricolare non influenza la prognosi"],"answer":"La coronaropatia aggiunge ischemia, infarto e rimodellamento alla disfunzione ventricolare","displayAnswer":"La coronaropatia aggiunge ischemia, infarto e rimodellamento alla disfunzione ventricolare","explanation":"CAD e scompenso sommano meccanismi sfavorevoli e si associano a mortalità maggiore rispetto alla sola CAD. La disfunzione non è necessariamente recuperabile con la sola apertura del vaso.","set":"D"},{"id":"q042","source":"16. Piccolo Rivascolarizzazione nel paziente con disfunzione ventricolare sinistra.pdf","page":15,"topic":"Revascularization and LV dysfunction","type":"mcq","prompt":"Un paziente con cicatrice ventricolare e TV monomorfa viene rivascolarizzato completamente ma continua ad avere episodi. Perché?","options":["L'ischemia è l'unico meccanismo possibile","La cicatrice scompare immediatamente dopo PCI","Il substrato cicatriziale di rientro può persistere anche dopo la correzione dell'ischemia","La TV monomorfa dipende soltanto dal nodo del seno","La rivascolarizzazione aumenta sempre il numero di vie accessorie"],"answer":"Il substrato cicatriziale di rientro può persistere anche dopo la correzione dell'ischemia","displayAnswer":"Il substrato cicatriziale di rientro può persistere anche dopo la correzione dell'ischemia","explanation":"La rivascolarizzazione può ridurre ischemia trigger, ma non elimina necessariamente circuiti di rientro nella cicatrice; possono servire ICD e/o ablazione.","set":"D"},{"id":"q046","source":"17. Ass. Pilato Rivascolarizzazione miocardica chirurgica.pdf","page":2,"topic":"Surgical revascularization","type":"mcq","prompt":"Quale abbinamento tra score e domanda clinica è corretto nella pianificazione di CABG?","options":["SYNTAX per complessità coronarica; STS/EuroSCORE II per rischio operatorio","CFR per rischio chirurgico; IMR per complessità anatomica","SYNTAX per diagnosticare sincope; STS per misurare FFR","CHA2DS2-VASc per sede della stenosi; GRACE per qualità del graft","TIMI per anatomia dei graft; QTc per mortalità operatoria"],"answer":"SYNTAX per complessità coronarica; STS/EuroSCORE II per rischio operatorio","displayAnswer":"SYNTAX per complessità coronarica; STS/EuroSCORE II per rischio operatorio","explanation":"Gli score rispondono a domande diverse: SYNTAX descrive complessità anatomica, mentre STS ed EuroSCORE II stimano rischio perioperatorio.","set":"D"},{"id":"q049","source":"17. Ass. Pilato Rivascolarizzazione miocardica chirurgica.pdf","page":9,"topic":"Surgical revascularization","type":"mcq","prompt":"Quando una tecnica off-pump può essere ragionevole?","options":["Perché garantisce sempre più graft","In tutti i pazienti perché è universalmente superiore","In pazienti selezionati e in centri con esperienza, quando evitare la circolazione extracorporea offre un vantaggio plausibile","Per evitare qualunque rischio emorragico","Solo quando non esistono coronarie trattabili"],"answer":"In pazienti selezionati e in centri con esperienza, quando evitare la circolazione extracorporea offre un vantaggio plausibile","displayAnswer":"In pazienti selezionati e in centri con esperienza, quando evitare la circolazione extracorporea offre un vantaggio plausibile","explanation":"Non esiste una superiorità assoluta off-pump/on-pump. Il risultato dipende da selezione, stabilità emodinamica, anatomia e competenza dell'équipe.","set":"D"},{"id":"q052","source":"18. Piccolo Rivascolarizzazione miocardica nelle sindromi coronariche acute.pdf","page":1,"topic":"ACS revascularization","type":"mcq","prompt":"Osserva il modello di guarigione della placca. Perché una SCA non va considerata soltanto come una stenosi fissa da dilatare?","options":["Rottura o erosione, trombosi e risposta di guarigione sono processi dinamici","La placca non cambia mai nel tempo","La PCI elimina immediatamente tutta l'aterosclerosi","L'ischemia acuta non coinvolge le piastrine","Ogni trombo è esclusivamente venoso"],"answer":"Rottura o erosione, trombosi e risposta di guarigione sono processi dinamici","displayAnswer":"Rottura o erosione, trombosi e risposta di guarigione sono processi dinamici","explanation":"La SCA nasce dall'interazione tra placca e trombo; la PCI tratta la lesione culprit, ma terapia antitrombotica e prevenzione secondaria agiscono sul processo sistemico.","image":"assets/figures/08-p001.jpg","imageAlt":"Figura di riferimento da 18. Piccolo Rivascolarizzazione miocardica nelle sindromi coronariche acute.pdf, pagina 1","imagePage":1,"set":"D"},{"id":"q060","source":"19. Piccolo Shock cardiogeno - rivascolarizzazione e supporto al circolo.pdf","page":1,"topic":"Cardiogenic shock","type":"mcq","prompt":"Un paziente necessita di supporto di flusso quasi completo e ossigenazione extracorporea. Quale dispositivo è più coerente?","options":["Loop recorder","IABP isolato","Pacemaker bicamerale","Filtro cavale","ECMO veno-arterioso"],"answer":"ECMO veno-arterioso","displayAnswer":"ECMO veno-arterioso","explanation":"L'ECMO VA può fornire diversi litri/minuto e supporto cardiopolmonare. IABP aumenta la portata in misura modesta e non ossigena il sangue.","set":"D"},{"id":"q063","source":"19. Piccolo Shock cardiogeno - rivascolarizzazione e supporto al circolo.pdf","page":8,"topic":"Cardiogenic shock","type":"mcq","prompt":"Uno studio su supporto microassiale nello shock mostra riduzione assoluta di mortalità ma più complicanze. Come va applicato il risultato?","options":["Sostituendo la rivascolarizzazione con il device","Selezionando pazienti, timing e centri capaci di gestire sanguinamento e complicanze vascolari","Ignorando gli eventi avversi","Considerando il device privo di rischio","Impiantando il dispositivo in ogni STEMI"],"answer":"Selezionando pazienti, timing e centri capaci di gestire sanguinamento e complicanze vascolari","displayAnswer":"Selezionando pazienti, timing e centri capaci di gestire sanguinamento e complicanze vascolari","explanation":"Il beneficio medio non elimina il trade-off. Indicazione, impianto precoce in pazienti appropriati e gestione esperta determinano il valore clinico.","set":"D"},{"id":"q067","source":"2. Strisciuglio - Lo studio elettrofisiologico_ indicazioni, tecnica di esecuzione, parametri registrati - 5 marzo.pdf","page":16,"topic":"Electrophysiology","type":"mcq","prompt":"Durante pacing ventricolare, l'attivazione atriale più precoce non è settale ma laterale sinistra. Quale reperto è più probabile?","options":["Blocco seno-atriale","Assenza completa di conduzione VA","Conduzione concentrica esclusiva del nodo AV","Conduzione retrograda attraverso una via accessoria laterale sinistra","Automaticità del nodo del seno"],"answer":"Conduzione retrograda attraverso una via accessoria laterale sinistra","displayAnswer":"Conduzione retrograda attraverso una via accessoria laterale sinistra","explanation":"Un'attivazione atriale eccentrica suggerisce una via accessoria o una tachicardia atriale; la sede più precoce orienta la localizzazione.","set":"D"},{"id":"q070","source":"2. Strisciuglio - Lo studio elettrofisiologico_ indicazioni, tecnica di esecuzione, parametri registrati - 5 marzo.pdf","page":7,"topic":"Electrophysiology","type":"mcq","prompt":"Un paziente con sincope e blocco di branca ha alta probabilità pre-test di malattia His-Purkinje. Quale esame può documentare il difetto di conduzione?","options":["Solo radiografia del torace","PET-FDG","Test cutaneo allergologico","Studio elettrofisiologico con misura dell'intervallo HV","Calcium score"],"answer":"Studio elettrofisiologico con misura dell'intervallo HV","displayAnswer":"Studio elettrofisiologico con misura dell'intervallo HV","explanation":"Il SEF può misurare conduzione infra-Hisiana e provocare blocco in pazienti selezionati; un loop recorder è più adatto quando la probabilità pre-test è bassa e serve documentazione prolungata.","set":"D"},{"id":"q074","source":"20. Di Serafino Fisiologia coronarica nel paziente candidato a rivascolarizzazione coronarica; ANOCA e INOCA.pdf","page":13,"topic":"Coronary physiology and INOCA","type":"mcq","prompt":"Quale differenza separa ANOCA da INOCA?","options":["ANOCA richiede sempre infarto","Sono sinonimi di STEMI","INOCA richiede evidenza di ischemia; ANOCA descrive angina con coronarie non ostruttive","ANOCA è definita da FFR patologico in una stenosi focale","INOCA richiede stenosi >90%"],"answer":"INOCA richiede evidenza di ischemia; ANOCA descrive angina con coronarie non ostruttive","displayAnswer":"INOCA richiede evidenza di ischemia; ANOCA descrive angina con coronarie non ostruttive","explanation":"I termini distinguono la presentazione anginosa dall'evidenza oggettiva di ischemia; entrambi richiedono di cercare il meccanismo.","set":"D"},{"id":"q077","source":"20. Di Serafino Fisiologia coronarica nel paziente candidato a rivascolarizzazione coronarica; ANOCA e INOCA.pdf","page":9,"topic":"Coronary physiology and INOCA","type":"mcq","prompt":"Dopo PCI angiograficamente soddisfacente, FFR resta <0,86. Qual è la lettura più utile?","options":["Persistono fisiologia sfavorevole e rischio, da spiegare con lesione residua, malattia diffusa o problema dello stent","Il residual SYNTAX sostituisce ogni misura fisiologica","La PCI è sicuramente perfetta","Indica sempre spasmo microvascolare","Il valore non ha significato prognostico"],"answer":"Persistono fisiologia sfavorevole e rischio, da spiegare con lesione residua, malattia diffusa o problema dello stent","displayAnswer":"Persistono fisiologia sfavorevole e rischio, da spiegare con lesione residua, malattia diffusa o problema dello stent","explanation":"La fisiologia post-PCI fornisce informazione incrementale rispetto all'aspetto angiografico e può guidare un controllo mirato del risultato.","set":"D"},{"id":"q081","source":"23. Di Seraf.  MINOCA (by giovanni vitale.pdf","page":6,"topic":"MINOCA","type":"mcq","prompt":"Osserva il percorso diagnostico. Perché un trattamento uguale per tutti i MINOCA è inadeguato?","options":["Tutti i casi sono causati da placca aterosclerotica","La diagnosi non richiede ulteriori indagini","MINOCA significa sempre miocardite","Le coronarie non ostruttive escludono danno miocardico","MINOCA è una sindrome con meccanismi differenti che richiedono terapie mirate"],"answer":"MINOCA è una sindrome con meccanismi differenti che richiedono terapie mirate","displayAnswer":"MINOCA è una sindrome con meccanismi differenti che richiedono terapie mirate","explanation":"Placca, spasmo, SCAD, embolia, disfunzione microvascolare e diagnosi alternative richiedono percorsi diversi. La coronarografia non ostruttiva apre l'indagine, non la conclude.","image":"assets/figures/12-p006.jpg","imageAlt":"Figura di riferimento da 23. Di Seraf.  MINOCA (by giovanni vitale.pdf, pagina 6","imagePage":6,"set":"D"},{"id":"q088","source":"23. Di Seraf.  MINOCA (by giovanni vitale.pdf","page":7,"topic":"MINOCA","type":"mcq","prompt":"Quale risultato dimostra il valore di una strategia diagnostica stratificata nel MINOCA?","options":["Evitare ogni esame dopo angiografia","Prescrivere lo stesso farmaco a tutti","Ridurre il bisogno di anamnesi","Identificare più spesso la causa e migliorare i sintomi con trattamento guidato dal fenotipo","Trasformare tutte le diagnosi in STEMI"],"answer":"Identificare più spesso la causa e migliorare i sintomi con trattamento guidato dal fenotipo","displayAnswer":"Identificare più spesso la causa e migliorare i sintomi con trattamento guidato dal fenotipo","explanation":"Definire il meccanismo consente una terapia coerente e può migliorare l'angina. Il beneficio deriva dall'abbinamento diagnosi-trattamento.","set":"D"},{"id":"q092","source":"25-26 Franzone - Terapia medica ottimale nelle sindromi coronariche acute e croniche.pdf","page":3,"topic":"Antiplatelet and medical therapy","type":"mcq","prompt":"Qual è il meccanismo antiaggregante dell'aspirina a basse dosi?","options":["Aumento della sintesi di trombossano","Blocco reversibile del recettore P2Y12","Attivazione della trombina","Inibizione diretta del fattore Xa","Inibizione irreversibile della COX-1 piastrinica e riduzione del trombossano A2"],"answer":"Inibizione irreversibile della COX-1 piastrinica e riduzione del trombossano A2","displayAnswer":"Inibizione irreversibile della COX-1 piastrinica e riduzione del trombossano A2","explanation":"Le piastrine non possono risintetizzare COX-1; l'effetto dura per la loro vita. Clopidogrel, prasugrel e ticagrelor agiscono invece sul P2Y12.","set":"D"},{"id":"q095","source":"25-26 Franzone - Terapia medica ottimale nelle sindromi coronariche acute e croniche.pdf","page":10,"topic":"Antiplatelet and medical therapy","type":"mcq","prompt":"Qual è il ruolo temporale più appropriato dei due score PRECISE-DAPT e DAPT?","options":["Entrambi misurano esclusivamente l'anatomia coronarica","DAPT sostituisce il giudizio clinico","PRECISE-DAPT all'inizio per il rischio emorragico; DAPT dopo un periodo non complicato per valutare estensione","DAPT prima della coronarografia e PRECISE-DAPT solo dopo cinque anni","PRECISE-DAPT identifica la sede della via accessoria"],"answer":"PRECISE-DAPT all'inizio per il rischio emorragico; DAPT dopo un periodo non complicato per valutare estensione","displayAnswer":"PRECISE-DAPT all'inizio per il rischio emorragico; DAPT dopo un periodo non complicato per valutare estensione","explanation":"Gli score supportano, non sostituiscono, la decisione. Rispondono a momenti e domande differenti del percorso antitrombotico.","set":"D"},{"id":"q099","source":"28. Cirillo Terapia antitrombotica nelle sindromi coronariche acute - dal pretrattamento alla dimissione.pdf","page":4,"topic":"Antithrombotic therapy","type":"mcq","prompt":"Osserva le curve rispetto al momento di somministrazione dell'eparina. Qual è il messaggio procedurale?","options":["L'anticoagulazione sostituisce la riperfusione","Il timing non influenza mai l'effetto","L'anticoagulante deve essere somministrato con timing che garantisca attività adeguata al momento della PCI","L'eparina va data solo dopo la rimozione della guaina","Più tardi è sempre meglio"],"answer":"L'anticoagulante deve essere somministrato con timing che garantisca attività adeguata al momento della PCI","displayAnswer":"L'anticoagulante deve essere somministrato con timing che garantisca attività adeguata al momento della PCI","explanation":"L'obiettivo è evitare trombosi procedurale assicurando un livello efficace quando si interviene, senza aumentare inutilmente il sanguinamento.","image":"assets/figures/15-p004.jpg","imageAlt":"Figura di riferimento da 28. Cirillo Terapia antitrombotica nelle sindromi coronariche acute - dal pretrattamento alla dimissione.pdf, pagina 4","imagePage":4,"set":"D"},{"id":"q104","source":"28. Cirillo Terapia antitrombotica nelle sindromi coronariche acute - dal pretrattamento alla dimissione.pdf","page":17,"topic":"Antithrombotic therapy","type":"mcq","prompt":"Dopo tre mesi di DAPT, un paziente ad alto rischio viene mantenuto con ticagrelor senza aspirina. Qual è l'obiettivo della strategia?","options":["Trattare una bradicardia","Indurre tolleranza all'aspirina","Aumentare la dose di anticoagulante","Eliminare ogni protezione antitrombotica","Ridurre sanguinamento mantenendo una potente inibizione P2Y12"],"answer":"Ridurre sanguinamento mantenendo una potente inibizione P2Y12","displayAnswer":"Ridurre sanguinamento mantenendo una potente inibizione P2Y12","explanation":"La monoterapia P2Y12 dopo DAPT breve è una strategia di de-escalation validata in popolazioni selezionate; non equivale a sospendere tutta la terapia.","set":"D"},{"id":"q109","source":"3. Rapacciuolo - Disfunzione del nodo del seno e del nodo AV- fisiopatologia, test diagnostici, trattamento.pdf","page":5,"topic":"Bradyarrhythmias","type":"mcq","prompt":"Durante esercizio compare blocco AV di grado maggiore con sintomi. Quale interpretazione è più preoccupante?","options":["Vasospasmo epicardico certo","Artefatto obbligato","Risposta fisiologica del nodo del seno","Miglioramento della conduzione","Malattia del sistema His-Purkinje che peggiora con l'aumento della frequenza"],"answer":"Malattia del sistema His-Purkinje che peggiora con l'aumento della frequenza","displayAnswer":"Malattia del sistema His-Purkinje che peggiora con l'aumento della frequenza","explanation":"Il blocco che compare o peggiora con sforzo può indicare malattia infra-Hisiana e richiede valutazione per pacing, non va considerato fisiologico.","set":"D"},{"id":"q112","source":"3. Rapacciuolo - Disfunzione del nodo del seno e del nodo AV- fisiopatologia, test diagnostici, trattamento.pdf","page":12,"topic":"Bradyarrhythmias","type":"mcq","prompt":"Perché il pacing può fallire nel prevenire una sincope riflessa con importante componente vasodepressiva?","options":["Trasforma la sincope in epilessia","Corregge la bradicardia ma non necessariamente la caduta di resistenze e pressione","Aumenta sempre la vasodilatazione","Non stimola mai i ventricoli","Elimina il ritorno venoso"],"answer":"Corregge la bradicardia ma non necessariamente la caduta di resistenze e pressione","displayAnswer":"Corregge la bradicardia ma non necessariamente la caduta di resistenze e pressione","explanation":"La sincope riflessa può avere componenti cardioinibitoria e vasodepressiva. Il pacing aiuta soprattutto quando la bradicardia/asistolia è dominante e documentata.","set":"D"},{"id":"q117","source":"31. Spaccarotella Dissezioni Coronariche Spontanee (1).pdf","page":3,"topic":"SCAD","type":"mcq","prompt":"Perché la coronarografia può sottodiagnosticare una SCAD di tipo 2?","options":["Il tipo 2 produce solo aneurismi","La SCAD non modifica il lume","Può apparire come un lungo restringimento liscio senza flap evidente","La dissezione è sempre calcifica","Il contrasto non entra mai nelle coronarie"],"answer":"Può apparire come un lungo restringimento liscio senza flap evidente","displayAnswer":"Può apparire come un lungo restringimento liscio senza flap evidente","explanation":"La compressione da ematoma intramurale può creare stenosi lunga e affusolata. Il riconoscimento del pattern evita stent non necessari.","set":"D"},{"id":"q120","source":"31. Spaccarotella Dissezioni Coronariche Spontanee (1).pdf","page":6,"topic":"SCAD","type":"mcq","prompt":"Quale situazione rende più appropriata una rivascolarizzazione urgente nella SCAD?","options":["Ischemia persistente, instabilità emodinamica o flusso compromesso in territorio critico","Assenza di sintomi e flusso TIMI 3","Troponina in calo con stabilità","Guarigione documentata","Solo ansia del paziente"],"answer":"Ischemia persistente, instabilità emodinamica o flusso compromesso in territorio critico","displayAnswer":"Ischemia persistente, instabilità emodinamica o flusso compromesso in territorio critico","explanation":"La strategia conservativa non è passività: si interviene quando il rischio ischemico supera quello procedurale.","set":"D"},{"id":"q124","source":"32. Losi - complicanze meccaniche dell' infarto.pdf","page":7,"topic":"Mechanical complications of MI","type":"mcq","prompt":"Nei giorni dopo un infarto, compare shock improvviso con nuovo soffio olosistolico. Quale diagnosi deve essere cercata subito con ecocardiografia?","options":["Sindrome di Brugada","Rottura del setto interventricolare o del muscolo papillare","Ipertensione isolata","Semplice angina stabile","WPW asintomatico"],"answer":"Rottura del setto interventricolare o del muscolo papillare","displayAnswer":"Rottura del setto interventricolare o del muscolo papillare","explanation":"Deterioramento acuto e nuovo soffio dopo IMA sono segnali d'allarme per complicanza meccanica. L'eco bedside distingue shunt, insufficienza mitralica e rottura di parete.","set":"D"},{"id":"q127","source":"32. Losi - complicanze meccaniche dell' infarto.pdf","page":9,"topic":"Mechanical complications of MI","type":"mcq","prompt":"Un paziente collassa improvvisamente dopo STEMI con attività elettrica senza polso e versamento pericardico. Quale complicanza è più probabile?","options":["AVNRT tipica","Restenosi cronica dello stent","Sincope vasovagale","CFR ridotta isolata","Rottura della parete libera con tamponamento"],"answer":"Rottura della parete libera con tamponamento","displayAnswer":"Rottura della parete libera con tamponamento","explanation":"La rottura libera può causare emopericardio, tamponamento e PEA. È un'emergenza meccanica distinta dalle aritmie defibrillabili.","set":"D"},{"id":"q131","source":"4. Pergola - Short QT, Long QT, TV idiopatica.pdf","page":5,"topic":"Inherited repolarization disorders","type":"mcq","prompt":"Perché la dispersione della ripolarizzazione aumenta il rischio di rientro ventricolare?","options":["Regioni già recuperate possono essere riattivate mentre altre sono ancora refrattarie","La conduzione diventa sempre bidirezionale rapida","Tutto il miocardio recupera simultaneamente","La CFR aumenta","Il nodo del seno smette di funzionare"],"answer":"Regioni già recuperate possono essere riattivate mentre altre sono ancora refrattarie","displayAnswer":"Regioni già recuperate possono essere riattivate mentre altre sono ancora refrattarie","explanation":"L'eterogeneità temporale crea gradiente di refrattarietà e blocco funzionale, favorendo circuiti e torsione di punta.","set":"D"},{"id":"q134","source":"4. Pergola - Short QT, Long QT, TV idiopatica.pdf","page":18,"topic":"Inherited repolarization disorders","type":"mcq","prompt":"Qual è il valore di un Holter a 12 derivazioni nel sospetto LQTS?","options":["Calcolare IMR","Diagnosticare SCAD","Valutare adattamento del QT a frequenza, sonno, risveglio e attività","Sostituire ogni test genetico","Misurare la stenosi coronarica"],"answer":"Valutare adattamento del QT a frequenza, sonno, risveglio e attività","displayAnswer":"Valutare adattamento del QT a frequenza, sonno, risveglio e attività","explanation":"La dinamica del QT può rivelare fenotipi non evidenti nel singolo ECG. Il risultato va interpretato con il contesto clinico.","set":"D"},{"id":"q138","source":"5. Rapacciuolo prevenzione SCD + dispositivi per HF 2.pdf","page":24,"topic":"Sudden cardiac death and devices","type":"mcq","prompt":"Osserva lo schema. Qual è il problema centrale della prevenzione primaria della morte improvvisa?","options":["Identificare il piccolo gruppo che avrà eventi tra molti pazienti apparentemente stabili","Ogni cardiopatia richiede un ICD","La FE predice perfettamente tutti gli eventi","Il defibrillatore esterno è inutile","Gli eventi avvengono solo in ospedale"],"answer":"Identificare il piccolo gruppo che avrà eventi tra molti pazienti apparentemente stabili","displayAnswer":"Identificare il piccolo gruppo che avrà eventi tra molti pazienti apparentemente stabili","explanation":"La stratificazione combina funzione, eziologia, cicatrice, genetica e storia. Nessun singolo marker separa perfettamente rischio e beneficio.","image":"assets/figures/20-p024.jpg","imageAlt":"Figura di riferimento da 5. Rapacciuolo prevenzione SCD + dispositivi per HF 2.pdf, pagina 24","imagePage":24,"set":"D"},{"id":"q144","source":"5. Rapacciuolo prevenzione SCD + dispositivi per HF 2.pdf","page":11,"topic":"Sudden cardiac death and devices","type":"mcq","prompt":"Perché episodi notturni di FV registrati da un ICD possono essere clinicamente silenti?","options":["La FV è sempre artefatto","Il sonno impedisce la defibrillazione","Il dispositivo rileva e termina rapidamente l'aritmia prima che il paziente percepisca o ricordi sintomi","L'ICD converte l'aritmia in stenosi","La FV notturna non riduce la portata"],"answer":"Il dispositivo rileva e termina rapidamente l'aritmia prima che il paziente percepisca o ricordi sintomi","displayAnswer":"Il dispositivo rileva e termina rapidamente l'aritmia prima che il paziente percepisca o ricordi sintomi","explanation":"La memoria del device documenta eventi non riferiti e permette di valutare appropriatezza, trigger e necessità di modifica terapeutica.","set":"D"},{"id":"q149","source":"5. Vergara -CRT e ICD Trial Clinici-.pdf","page":16,"topic":"Cardiac resynchronization therapy","type":"mcq","prompt":"In un paziente candidato a CRT con indicazione anche alla prevenzione della morte improvvisa, quale sistema è più coerente?","options":["CRT-D","Pacemaker monocamerale senza resincronizzazione","DAE esterno come terapia definitiva","Loop recorder","CCM isolata"],"answer":"CRT-D","displayAnswer":"CRT-D","explanation":"CRT-D combina resincronizzazione e defibrillazione; CRT-P è appropriata quando non serve la funzione ICD o il bilancio clinico la sconsiglia.","set":"D"},{"id":"q152","source":"6 Strisciugno Sincope.pdf","page":2,"topic":"Syncope","type":"mcq","prompt":"Perché la prima valutazione della sincope deve includere stratificazione del rischio oltre alla diagnosi?","options":["La causa non influenza la prognosi","La sincope riflessa è sempre fatale","Tutte le sincopi richiedono ricovero","Alcune cause cardiache hanno bassa frequenza ma alta mortalità e richiedono percorso urgente","L'ECG non modifica il rischio"],"answer":"Alcune cause cardiache hanno bassa frequenza ma alta mortalità e richiedono percorso urgente","displayAnswer":"Alcune cause cardiache hanno bassa frequenza ma alta mortalità e richiedono percorso urgente","explanation":"Anamnesi, esame, pressione ortostatica ed ECG identificano segnali d'allarme e guidano ricovero, monitoraggio o gestione ambulatoriale.","set":"D"},{"id":"q155","source":"6 Strisciugno Sincope.pdf","page":8,"topic":"Syncope","type":"mcq","prompt":"Quando il pacing è chiaramente indicato in un paziente con sincope?","options":["In presenza di ipotensione ortostatica senza bradicardia","Quando è documentata una bradiaritmia causale non reversibile","Per sola ansia","Dopo un singolo capogiro","In ogni sincope riflessa"],"answer":"Quando è documentata una bradiaritmia causale non reversibile","displayAnswer":"Quando è documentata una bradiaritmia causale non reversibile","explanation":"Il pacing tratta la componente bradicardica. La documentazione e l'esclusione di cause reversibili evitano impianti inutili.","set":"D"},{"id":"q159","source":"6. Strisciuglio Wolff Parkinson White.pdf","page":1,"topic":"WPW and accessory pathways","type":"mcq","prompt":"Perché una via accessoria atrioventricolare produce preeccitazione?","options":["Prolunga obbligatoriamente il PR","Blocca il nodo del seno","Rallenta sempre il fascio di His","Aumenta la riserva coronarica","Bypassa il ritardo fisiologico del nodo AV e attiva precocemente il ventricolo"],"answer":"Bypassa il ritardo fisiologico del nodo AV e attiva precocemente il ventricolo","displayAnswer":"Bypassa il ritardo fisiologico del nodo AV e attiva precocemente il ventricolo","explanation":"Il fascio muscolare collega atrio e ventricolo fuori dal nodo AV. Se conduce in senso anterogrado, una porzione ventricolare viene depolarizzata in anticipo.","set":"D"},{"id":"q162","source":"6. Strisciuglio Wolff Parkinson White.pdf","page":7,"topic":"WPW and accessory pathways","type":"mcq","prompt":"Perché più vie accessorie rendono meno affidabile la localizzazione basata sul solo ECG?","options":["Normalizzano il PR","Eliminano l'onda delta","Rendono sempre il QRS stretto","I vettori di preeccitazione si combinano e possono cambiare con la conduzione relativa","Impediscono ogni tachicardia"],"answer":"I vettori di preeccitazione si combinano e possono cambiare con la conduzione relativa","displayAnswer":"I vettori di preeccitazione si combinano e possono cambiare con la conduzione relativa","explanation":"Gli algoritmi ECG assumono spesso una singola via dominante. Vie multiple o cardiopatia strutturale possono produrre morfologie composite.","set":"D"},{"id":"q166","source":"7. Vergara Tachicardia da rientro nodale 2.pdf","page":19,"topic":"AVNRT","type":"mcq","prompt":"Osserva l'algoritmo delle tachicardie a QRS stretto. Una tachicardia regolare con RP molto corto e P non visibile è più compatibile con:","options":["Flutter atriale sempre 1:1","AVNRT tipica","Bradicardia sinusale","Tachicardia ventricolare lenta","Fibrillazione atriale"],"answer":"AVNRT tipica","displayAnswer":"AVNRT tipica","explanation":"Nella AVNRT slow-fast atrio e ventricolo sono attivati quasi simultaneamente, perciò la P retrograda è nascosta o immediatamente dopo il QRS.","image":"assets/figures/24-p019.jpg","imageAlt":"Figura di riferimento da 7. Vergara Tachicardia da rientro nodale 2.pdf, pagina 19","imagePage":19,"set":"D"},{"id":"q172","source":"7. Vergara Tachicardia da rientro nodale 2.pdf","page":23,"topic":"AVNRT","type":"mcq","prompt":"Perché una tachicardia da rientro può diventare quasi incessante?","options":["Ogni extrasistole blocca entrambe le vie","Il circuito resta disponibile e si riavvia facilmente dopo interruzioni brevi","Il nodo del seno elimina la via lenta","La conduzione retrograda è assente","Il circuito è anatomicamente interrotto"],"answer":"Il circuito resta disponibile e si riavvia facilmente dopo interruzioni brevi","displayAnswer":"Il circuito resta disponibile e si riavvia facilmente dopo interruzioni brevi","explanation":"Proprietà di conduzione e refrattarietà possono favorire continua riinduzione. La persistenza clinica non implica necessariamente automaticità.","set":"D"},{"id":"q176","source":"8. Vergara Sindromi Genetiche Vergara (Brugada, ER, CPVT) 2.pdf","page":13,"topic":"Inherited arrhythmia syndromes","type":"mcq","prompt":"Perché CMR e dati anatomopatologici hanno modificato la visione della Brugada come malattia puramente elettrica?","options":["Escludono ogni ruolo dei canali ionici","Dimostrano sempre infarto transmurale","Mostrano una via accessoria","Identificano stenosi del tronco comune","In alcuni pazienti mostrano alterazioni strutturali sottili, soprattutto del tratto di efflusso destro"],"answer":"In alcuni pazienti mostrano alterazioni strutturali sottili, soprattutto del tratto di efflusso destro","displayAnswer":"In alcuni pazienti mostrano alterazioni strutturali sottili, soprattutto del tratto di efflusso destro","explanation":"Fenotipo elettrico e substrato strutturale possono coesistere. La sindrome resta eterogenea e non va ridotta a un unico meccanismo.","set":"D"},{"id":"q180","source":"8. Vergara Sindromi Genetiche Vergara (Brugada, ER, CPVT) 2.pdf","page":36,"topic":"Inherited arrhythmia syndromes","type":"mcq","prompt":"In CPVT con eventi nonostante beta-blocco ottimale, quale opzione può ridurre il drive adrenergico?","options":["Simpaticectomia cardiaca sinistra in pazienti selezionati","Stent coronarico","Aspirina ad alte dosi","DAPT","Ablazione del nodo AV"],"answer":"Simpaticectomia cardiaca sinistra in pazienti selezionati","displayAnswer":"Simpaticectomia cardiaca sinistra in pazienti selezionati","explanation":"La simpaticectomia è un'aggiunta nei non responder, insieme a ottimizzazione farmacologica e valutazione di flecainide/ICD secondo il rischio.","set":"D"},{"id":"q184","source":"9. Ciampi Ecostress.pdf","page":13,"topic":"Stress echocardiography","type":"mcq","prompt":"Perché la porzione medio-distale dell'IVA è spesso scelta per misurare CFVR?","options":["È sempre priva di stenosi","È relativamente accessibile al Doppler e ha consolidato valore prognostico","È l'unica coronaria con flusso diastolico","Non cambia mai angolo","Perfunde solo il ventricolo destro"],"answer":"È relativamente accessibile al Doppler e ha consolidato valore prognostico","displayAnswer":"È relativamente accessibile al Doppler e ha consolidato valore prognostico","explanation":"La misura richiede mantenere segmento e angolo comparabili tra riposo e stress; errori di campionamento possono simulare variazioni.","set":"D"},{"id":"q187","source":"9. Ciampi Ecostress.pdf","page":18,"topic":"Stress echocardiography","type":"mcq","prompt":"In un paziente con ANOCA, l'ecostress mostra CFVR ridotta ma nessuna alterazione segmentaria. Quale endotipo è plausibile?","options":["WPW","AVNRT","Occlusione focale certa del tronco comune","Disfunzione microvascolare","Rottura del setto"],"answer":"Disfunzione microvascolare","displayAnswer":"Disfunzione microvascolare","explanation":"Una risposta di flusso globale ridotta senza difetto regionale può indicare CMD. Test invasivi possono distinguere resistenza elevata e vasospasmo.","set":"D"},{"id":"q191","source":"Lezione Gargiulo 2026.pdf","page":7,"topic":"ACS risk and antithrombotic strategy","type":"mcq","prompt":"Perché l'effetto antiaggregante immediato di prasugrel non equivale automaticamente a beneficio clinico in ogni paziente?","options":["Prasugrel è un anticoagulante","Il farmaco non raggiunge le piastrine","L'inibizione piastrinica non ha effetti clinici","Maggiore potenza riduce ischemia ma può aumentare sanguinamento; servono indicazione e selezione","Tutti hanno lo stesso rischio"],"answer":"Maggiore potenza riduce ischemia ma può aumentare sanguinamento; servono indicazione e selezione","displayAnswer":"Maggiore potenza riduce ischemia ma può aumentare sanguinamento; servono indicazione e selezione","explanation":"La farmacodinamica è solo una parte della decisione. Età, peso, storia di ictus e strategia invasiva influenzano il bilancio.","set":"D"},{"id":"q194","source":"Lezione Gargiulo 2026.pdf","page":15,"topic":"ACS diagnosis","type":"mcq","prompt":"Perché il paradigma OMI può identificare pazienti urgenti non classificati come STEMI classico?","options":["Solo aVR indica ogni OMI","OMI significa troponina negativa","La clinica non è rilevante","Un'occlusione acuta può produrre pattern ECG non conformi ai criteri millimetrici tradizionali","NSTEMI non può avere occlusione"],"answer":"Un'occlusione acuta può produrre pattern ECG non conformi ai criteri millimetrici tradizionali","displayAnswer":"Un'occlusione acuta può produrre pattern ECG non conformi ai criteri millimetrici tradizionali","explanation":"Pattern come de Winter, Aslanger o segni laterali alti possono indicare occlusione. ECG, sintomi, eco e dinamica devono essere integrati.","set":"D"},{"id":"q198","source":"guidelines 2023-SCA.pdf","page":41,"topic":"ACS guidelines","type":"mcq","prompt":"Un paziente con ACS e fibrillazione atriale ha indicazione cronica a OAC. Qual è il principio raccomandato durante PCI?","options":["Aggiungere due anticoagulanti","Interrompere sempre OAC e fare bridging","Usare triplice terapia indefinita","Evitare ogni antiaggregante anche durante stent","Continuare l'anticoagulazione indicata e minimizzare durata della triplice terapia"],"answer":"Continuare l'anticoagulazione indicata e minimizzare durata della triplice terapia","displayAnswer":"Continuare l'anticoagulazione indicata e minimizzare durata della triplice terapia","explanation":"L'indicazione a OAC va rivalutata ma, se valida, la strategia combina protezione embolica e dello stent riducendo il tempo di esposizione multipla.","set":"D"}]};
